resolved_issues.body:
### Description

Certain delays between last message FIFO write and  `HMAC_CMD_HASH_STOP_BIT` and `HMAC_CMD_HASH_PROCESS` commands cause the `HMAC.STATUS` register to get stuck with `hmac_idle` bit cleared. 

Reproduction steps (pseudo-code): 

```c
 status = msg_fifo_write(data, len - leftover_len);

 // delay here, even  this small is enough
 for (size_t i = 0; i < 10; i = launder32(i + 1))
    ;

 // Time to tell HMAC HWIP to stop, because we do not have enough message
 // bytes for another round.
 uint32_t cmd_reg =
     bitfield_bit32_write(HMAC_CMD_REG_RESVAL, HMAC_CMD_HASH_STOP_BIT, 1);
 abs_mmio_write32(kHmacBaseAddr + HMAC_CMD_REG_OFFSET, cmd_reg);

 // Wait for HMAC HWIP operation to be completed.
 // In the error condition, this function will block forever.
 status = hmac_idle_wait();
```

During regular operating conditions, interrupts can fire at any time, causing delays similar to what is captured in the reproduction steps. This may cause hangs in the field that will be very difficult to debug / root cause.


Issue reported by @vsukhoml. 
CC: @vogelpi, @martin-velay, @johannheyszl, @gdessouky

fix_patch:
diff --git a/hw/ip/prim/rtl/prim_sha2.sv b/hw/ip/prim/rtl/prim_sha2.sv
index 27cf8d298800a..ec9ac5ccab77d 100644
--- a/hw/ip/prim/rtl/prim_sha2.sv
+++ b/hw/ip/prim/rtl/prim_sha2.sv
@@ -332,6 +332,10 @@ module prim_sha2 import prim_sha2_pkg::*;
           // Wait until it is filled
           fifo_st_d          = FifoLoadFromFifo;
           update_w_from_fifo = 1'b0;
+          if (msg_feed_complete) begin
+            fifo_st_d       = FifoIdle;
+            hash_done_next  = 1'b1;
+          end
         end else if (w_index_q == 4'd 15) begin
           fifo_st_d = FifoWait;
           // To increment w_index and it rolls over to 0
@@ -443,13 +447,26 @@ module prim_sha2 import prim_sha2_pkg::*;
     if (!sha_en_i || hash_go) sha_st_d  = ShaIdle;
   end

+  logic update_digest_q, update_digest_d;
+
   // Determine whether a digest is being computed for a complete block: when `update_digest` is set,
   // this module is not waiting for more data from the FIFO, and `message_length_i` is zero modulo a
   // complete block (512 bit for SHA2_256 and 1024 bit for SHA2_384 and SHA2_512).
-  assign digest_on_blk_o = update_digest && (fifo_st_q == FifoIdle) && (
+  assign digest_on_blk_o = (update_digest || update_digest_q) && (fifo_st_q == FifoIdle) && (
       (digest_mode_flag_q == SHA2_256                 && message_length_i[8:0] == '0) ||
       (digest_mode_flag_q inside {SHA2_384, SHA2_512} && message_length_i[9:0] == '0));

+  assign update_digest_d = digest_on_blk_o ? 1'b0 :
+                           update_digest   ? 1'b1 : update_digest_q;
+
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (!rst_ni) begin
+      update_digest_q <= 1'b0;
+    end else begin
+      update_digest_q <= update_digest_d;
+    end
+  end
+
   assign one_chunk_done = ((digest_mode_flag_q == SHA2_256 || ~MultimodeEn)
                           && (round_q == 7'd63)) ? 1'b1 :
                           (((digest_mode_flag_q == SHA2_384) || (digest_mode_flag_q == SHA2_512))

tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -uo pipefail

TEST_NAME="prim_sha2_hash_stop_hang"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import prim_sha2_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;

  logic              wipe_secret_i = 1'b0;
  sha_word32_t       wipe_v_i = '0;
  logic              fifo_rvalid_i = 1'b0;
  sha_fifo64_t       fifo_rdata_i = '0;
  logic              fifo_rready_o;
  logic              sha_en_i = 1'b0;
  logic              hash_start_i = 1'b0;
  logic              hash_stop_i = 1'b0;
  logic              hash_continue_i = 1'b0;
  digest_mode_e      digest_mode_i = SHA2_256;
  logic              hash_process_i = 1'b0;
  logic              hash_done_o;
  logic [63:0]       message_length_i = 64'd512;
  sha_word64_t [7:0] digest_i = '{default: '0};
  logic [7:0]        digest_we_i = '0;
  sha_word64_t [7:0] digest_o;
  logic              digest_on_blk_o;
  fifoctl_state_e    fifo_st_o;
  logic              hash_running_o;
  logic              idle_o;

  logic saw_hash_done;

  prim_sha2 #(
    .MultimodeEn(0)
  ) dut (
    .clk_i,
    .rst_ni,
    .wipe_secret_i,
    .wipe_v_i,
    .fifo_rvalid_i,
    .fifo_rdata_i,
    .fifo_rready_o,
    .sha_en_i,
    .hash_start_i,
    .hash_stop_i,
    .hash_continue_i,
    .digest_mode_i,
    .hash_process_i,
    .hash_done_o,
    .message_length_i,
    .digest_i,
    .digest_we_i,
    .digest_o,
    .digest_on_blk_o,
    .fifo_st_o,
    .hash_running_o,
    .idle_o
  );

  always #1 clk_i = ~clk_i;

  always @(posedge clk_i) begin
    if (hash_done_o) begin
      saw_hash_done <= 1'b1;
      $display("INFO: hash_done asserted at t=%0t fifo_st=%0d idle=%0b", $time, fifo_st_o, idle_o);
    end
  end

  task automatic pulse_hash_start();
    begin
      hash_start_i <= 1'b1;
      @(posedge clk_i);
      hash_start_i <= 1'b0;
    end
  endtask

  task automatic pulse_hash_stop();
    begin
      hash_stop_i <= 1'b1;
      @(posedge clk_i);
      hash_stop_i <= 1'b0;
    end
  endtask

  task automatic send_word(input logic [31:0] word);
    begin
      fifo_rdata_i.data <= {32'h0, word};
      fifo_rdata_i.mask <= 8'h0f;
      fifo_rvalid_i <= 1'b1;
      do begin
        @(posedge clk_i);
      end while (!fifo_rready_o);
      fifo_rvalid_i <= 1'b0;
      fifo_rdata_i <= '0;
      @(posedge clk_i);
    end
  endtask

  initial begin
    saw_hash_done = 1'b0;
    repeat (5) @(posedge clk_i);
    rst_ni <= 1'b1;
    repeat (2) @(posedge clk_i);

    sha_en_i <= 1'b1;
    repeat (2) @(posedge clk_i);

    pulse_hash_start();

    for (int i = 0; i < 16; i++) begin
      send_word(32'h1000_0000 + i);
    end

    repeat (70) @(posedge clk_i);
    pulse_hash_stop();

    repeat (200) begin
      @(posedge clk_i);
      if (saw_hash_done && idle_o) begin
        $display("RUNTIME PASS: hash_done observed and DUT returned to idle");
        $finish;
      end
    end

    $display("RUNTIME FAIL: timeout waiting for hash_done+idle fifo_st=%0d idle=%0b hash_done=%0b digest_on_blk=%0b",
             fifo_st_o, idle_o, hash_done_o, digest_on_blk_o);
    $fatal(1);
  end
endmodule
EOF

vcs -full64 -sverilog \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  -top tb \
  -o "${TB_DIR}/simv" \
  -Mdir="${TB_DIR}/csrc" \
  /home/opentitan/hw/ip/prim/rtl/prim_sha2_pkg.sv \
  /home/opentitan/hw/ip/prim/rtl/prim_sha2_pad.sv \
  /home/opentitan/hw/ip/prim/rtl/prim_sha2.sv \
  "${TB_DIR}/tb.sv" \
  -l "${COMPILE_LOG}"
compile_rc=$?
if [ "${compile_rc}" -ne 0 ]; then
  emit_result "FAIL"
  exit "${compile_rc}"
fi

"${TB_DIR}/simv" | tee "${RUN_LOG}"
run_rc=${PIPESTATUS[0]}

if [ "${run_rc}" -eq 0 ] && \
   grep -q "RUNTIME PASS:" "${RUN_LOG}" && \
   ! grep -q "RUNTIME FAIL:" "${RUN_LOG}"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

