diff --git a/hw/ip/hmac/rtl/hmac_core.sv b/hw/ip/hmac/rtl/hmac_core.sv
index dc4cd4fa185ed..967dd8ee78440 100644
--- a/hw/ip/hmac/rtl/hmac_core.sv
+++ b/hw/ip/hmac/rtl/hmac_core.sv
@@ -79,6 +79,9 @@ module hmac_core import prim_sha2_pkg::*; (

   logic hmac_sha_rvalid;

+  logic idle_d, idle_q;
+  logic reg_hash_stop_d, reg_hash_stop_q;
+
   typedef enum logic [1:0] {
     SelIPad,
     SelOPad,
@@ -233,9 +236,9 @@ module hmac_core import prim_sha2_pkg::*; (

   always_comb begin
     unique case (digest_size_i)
-      SHA2_256: txcnt_eq_blksz = (txcount[BlockSizeBitsSHA256:0] == BlockSizeBSBSHA256);
-      SHA2_384: txcnt_eq_blksz = (txcount[BlockSizeBitsSHA512:0] == BlockSizeBSBSHA512);
-      SHA2_512: txcnt_eq_blksz = (txcount[BlockSizeBitsSHA512:0] == BlockSizeBSBSHA512);
+      SHA2_256: txcnt_eq_blksz = (txcount[BlockSizeBitsSHA256-1:0] == '0) && (txcount != '0);
+      SHA2_384: txcnt_eq_blksz = (txcount[BlockSizeBitsSHA512-1:0] == '0) && (txcount != '0);
+      SHA2_512: txcnt_eq_blksz = (txcount[BlockSizeBitsSHA512-1:0] == '0) && (txcount != '0);
       default : txcnt_eq_blksz = '0;
     endcase
   end
@@ -323,13 +326,21 @@ module hmac_core import prim_sha2_pkg::*; (

     unique case (st_q)
       StIdle: begin
+        // reset round to Inner
+        // we always switch context into inner round since outer round computes once over
+        // single block at the end (outer key pad + inner hash)
+        update_round = 1'b1;
+        round_d      = Inner;
         if (hmac_en_i && reg_hash_start_i) begin
-          st_d = StIPad;
+          st_d = StIPad; // start at StIPad if told to start

           clr_txcount  = 1'b1;
-          update_round = 1'b1;
-          round_d      = Inner;
           hash_start   = 1'b1;
+        end else if (hmac_en_i && reg_hash_continue_i) begin
+          st_d = StMsg; // skip StIPad if told to continue - assumed it finished StIPad
+
+          load_txcount  = 1'b1;
+          hash_continue = 1'b1;
         end else begin
           st_d = StIdle;
         end
@@ -353,16 +364,15 @@ module hmac_core import prim_sha2_pkg::*; (
         sel_rdata   = SelFifo;
         fifo_wsel_o = (round_q == Outer);

-        if (round_q == Inner && reg_hash_continue_i) begin
-          load_txcount  = 1'b1;
-          hash_continue = 1'b1;
-        end
-
         if ( (((round_q == Inner) && reg_hash_process_flag) || (round_q == Outer))
             && (txcount >= sha_message_length_o)) begin
           st_d    = StWaitResp;
           hmac_sha_rvalid = 1'b0; // block
           hash_process = (round_q == Outer);
+        end else if (txcnt_eq_blksz && reg_hash_stop_q && (round_q == Inner)) begin
+          st_d =  StWaitResp; // to wait on sha_hash_done_i
+
+          hmac_sha_rvalid = 1'b0;
         end else begin
           st_d            = StMsg;
           hmac_sha_rvalid = fifo_rvalid_i;
@@ -376,7 +386,11 @@ module hmac_core import prim_sha2_pkg::*; (
           if (round_q == Outer) begin
             st_d = StDone;
           end else begin // round_q == Inner
-            st_d = StPushToMsgFifo;
+            if (reg_hash_stop_q) begin
+              st_d = StDone;
+            end else begin
+              st_d = StPushToMsgFifo;
+            end
           end
         end else begin
           st_d = StWaitResp;
@@ -389,7 +403,7 @@ module hmac_core import prim_sha2_pkg::*; (
         fifo_wvalid_o      = 1'b1;
         clr_fifo_wdata_sel = 1'b0;

-        if (fifo_wready_i && (((fifo_wdata_sel_o == 4'd7)  && (digest_size_i == SHA2_256)) ||
+        if (fifo_wready_i && (((fifo_wdata_sel_o == 4'd7) && (digest_size_i == SHA2_256)) ||
                              ((fifo_wdata_sel_o == 4'd15) && (digest_size_i == SHA2_512)) ||
                              ((fifo_wdata_sel_o == 4'd11) && (digest_size_i == SHA2_384)))) begin

@@ -434,15 +448,29 @@ module hmac_core import prim_sha2_pkg::*; (
     endcase
   end

+  // raise reg_hash_stop_d flag at reg_hash_stop_i and keep it until sha_hash_done_i is asserted
+  // to indicate the hashing operation on current block has completed
+  assign reg_hash_stop_d = (reg_hash_stop_i == 1'b1)                            ? 1'b1 :
+                           (sha_hash_done_i == 1'b1 && reg_hash_stop_q == 1'b1) ? 1'b0 :
+                                                                                  reg_hash_stop_q;
+
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (!rst_ni) begin
+      reg_hash_stop_q <= 1'b0;
+    end else begin
+      reg_hash_stop_q <= reg_hash_stop_d;
+    end
+  end
+
   // Idle status signaling: This module ..
-  logic idle_d, idle_q;
   assign idle_d =
       // .. is not idle when told to start or continue
       (reg_hash_start_i || reg_hash_continue_i) ? 1'b0 :
       // .. is idle when the FSM is in the Idle state
       (st_q == StIdle) ? 1'b1 :
-      // .. is idle when it has processed a complete block of a message and is told to stop
-      (st_q == StMsg && txcnt_eq_blksz && reg_hash_stop_i) ? 1'b1 :
+      // .. is idle when it has processed a complete block of a message and is told to stop in any
+      // FSM state
+      (txcnt_eq_blksz && reg_hash_stop_d) ? 1'b1 :
       // .. and keeps the current idle state in all other cases.
       idle_q;

tb_script:
#!/bin/bash
cd /home/opentitan
if [ $? -ne 0 ]; then
  exit 1
fi
set +e

TEST_NAME="hmac_ctx_switch_stop_start"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

emit_result() {
  local status="$1"
  local rc="$2"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "$rc"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'SV'
module tb;
  import prim_sha2_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic [1023:0] secret_key_i;
  logic hmac_en_i;
  digest_mode_e digest_size_i;
  key_length_e key_length_i;
  logic reg_hash_start_i;
  logic reg_hash_stop_i;
  logic reg_hash_continue_i;
  logic reg_hash_process_i;
  logic hash_done_o;
  logic sha_hash_start_o;
  logic sha_hash_continue_o;
  logic sha_hash_process_o;
  logic sha_hash_done_i;
  logic sha_rvalid_o;
  sha_fifo32_t sha_rdata_o;
  logic sha_rready_i;
  logic fifo_rvalid_i;
  sha_fifo32_t fifo_rdata_i;
  logic fifo_rready_o;
  logic fifo_wsel_o;
  logic fifo_wvalid_o;
  logic [3:0] fifo_wdata_sel_o;
  logic fifo_wready_i;
  logic [63:0] message_length_i;
  logic [63:0] sha_message_length_o;
  logic idle_o;

  hmac_core dut (
    .clk_i,
    .rst_ni,
    .secret_key_i,
    .hmac_en_i,
    .digest_size_i,
    .key_length_i,
    .reg_hash_start_i,
    .reg_hash_stop_i,
    .reg_hash_continue_i,
    .reg_hash_process_i,
    .hash_done_o,
    .sha_hash_start_o,
    .sha_hash_continue_o,
    .sha_hash_process_o,
    .sha_hash_done_i,
    .sha_rvalid_o,
    .sha_rdata_o,
    .sha_rready_i,
    .fifo_rvalid_i,
    .fifo_rdata_i,
    .fifo_rready_o,
    .fifo_wsel_o,
    .fifo_wvalid_o,
    .fifo_wdata_sel_o,
    .fifo_wready_i,
    .message_length_i,
    .sha_message_length_o,
    .idle_o
  );

  always #5 clk_i = ~clk_i;

  task automatic tick(input int n);
    repeat (n) begin
      @(posedge clk_i);
      #1;
    end
  endtask

  task automatic pulse_start;
    reg_hash_start_i = 1'b1;
    #1;
    @(posedge clk_i);
    #1;
    reg_hash_start_i = 1'b0;
  endtask

  task automatic pulse_stop;
    reg_hash_stop_i = 1'b1;
    #1;
    @(posedge clk_i);
    #1;
    reg_hash_stop_i = 1'b0;
  endtask

  task automatic pulse_sha_done;
    sha_hash_done_i = 1'b1;
    #1;
    @(posedge clk_i);
    #1;
    sha_hash_done_i = 1'b0;
  endtask

  task automatic wait_for_pre_stop_point;
    int cycles;
    cycles = 0;
    while (!(dut.st_q == 3'd2 && dut.round_q == 1'b0 && dut.txcount == 64'd992)) begin
      @(posedge clk_i);
      #1;
      cycles++;
      if (cycles > 96) begin
        $display("TB FAIL: Timed out waiting for pre-stop point, st=%0d txcount=%0d", dut.st_q,
                 dut.txcount);
        $fatal(1, "Timed out waiting for pre-stop point");
      end
    end
  endtask

  task automatic wait_for_idle_state;
    int cycles;
    cycles = 0;
    while (dut.st_q != 3'd0) begin
      @(posedge clk_i);
      #1;
      cycles++;
      if (cycles > 12) begin
        $display("TB FAIL: Core never returned to StIdle after stop/hash_done, st=%0d idle_o=%0b txcount=%0d",
                 dut.st_q, idle_o, dut.txcount);
        $fatal(1, "Core never returned to StIdle after stop/hash_done");
      end
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    secret_key_i = 1024'h0123_4567_89ab_cdef;
    hmac_en_i = 1'b1;
    digest_size_i = SHA2_256;
    key_length_i = Key_256;
    reg_hash_start_i = 1'b0;
    reg_hash_stop_i = 1'b0;
    reg_hash_continue_i = 1'b0;
    reg_hash_process_i = 1'b0;
    sha_hash_done_i = 1'b0;
    sha_rready_i = 1'b1;
    fifo_rvalid_i = 1'b1;
    fifo_rdata_i = '{data: 32'hdeadbeef, mask: 4'hf};
    fifo_wready_i = 1'b1;
    message_length_i = 64'd2048;

    tick(2);
    rst_ni = 1'b1;
    tick(2);

    pulse_start();
    wait_for_pre_stop_point();
    $display("INFO pre-stop point: st=%0d txcount=%0d idle=%0b", dut.st_q, dut.txcount, idle_o);

    pulse_stop();
    $display("INFO stop observed: st=%0d txcount=%0d idle=%0b", dut.st_q, dut.txcount, idle_o);

    tick(1);
    pulse_sha_done();
    wait_for_idle_state();
    $display("INFO returned idle: st=%0d txcount=%0d idle=%0b", dut.st_q, dut.txcount, idle_o);

    reg_hash_start_i = 1'b1;
    #1;
    if (!sha_hash_start_o) begin
      $display("TB FAIL: new start did not trigger sha_hash_start_o once core was supposed to be idle");
      $fatal(1, "New start did not trigger sha_hash_start_o");
    end
    @(posedge clk_i);
    #1;
    reg_hash_start_i = 1'b0;

    $display("TB PASS");
    $finish;
  end
endmodule
SV

vcs -full64 -sverilog -timescale=1ns/1ps \
  -l "$TB_DIR/compile.log" \
  -o "$TB_DIR/simv" \
  hw/ip/prim/rtl/prim_sha2_pkg.sv \
  hw/ip/hmac/rtl/hmac_core.sv \
  "$TB_DIR/tb.sv"
compile_rc=$?

if [ $compile_rc -ne 0 ]; then
  cat "$TB_DIR/compile.log"
  emit_result "FAIL" "$compile_rc"
fi

"$TB_DIR/simv" -l "$TB_DIR/run.log"
run_rc=$?

if [ -f "$TB_DIR/run.log" ]; then
  cat "$TB_DIR/run.log"
fi

if [ $run_rc -eq 0 ] && grep -q "TB PASS" "$TB_DIR/run.log"; then
  emit_result "PASS" 0
fi

emit_result "FAIL" "${run_rc:-1}"

