tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan || exit 1

export PATH="/tools/riscv/bin:/tools/verible/bin:$PATH"

TEST_NAME="csrng_cmd_stage_hang"
SCRATCH_ROOT="/home/opentitan/.tb_csrng_cmd_stage_hang"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

inject_test() {
  mkdir -p hw/ip/csrng/dv/env/seq_lib hw/ip/csrng/dv/tests

  cat > hw/ip/csrng/dv/env/seq_lib/csrng_cmd_stage_hang_vseq.sv <<'SVEOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class csrng_cmd_stage_hang_vseq extends csrng_base_vseq;
  `uvm_object_utils(csrng_cmd_stage_hang_vseq)
  `uvm_object_new

  csrng_item cs_item;

  task automatic wait_cmd_req_done_short(string step_name);
    `DV_SPINWAIT(
      forever begin
        uvm_reg_data_t act_data;
        csr_rd(.ptr(ral.intr_state.cs_cmd_req_done), .value(act_data));
        if (act_data == 1'b1) break;
      end,
      $sformatf("timeout waiting for cmd_req_done after %s", step_name),
      200_000
    )
    csr_rd_check(.ptr(ral.sw_cmd_sts.cmd_sts), .compare_value(CMD_STS_SUCCESS));
    csr_wr(.ptr(ral.intr_state), .value(1 << CmdReqDone));
  endtask

  virtual task body();
    super.body();

    cfg.csrng_assert_vif.assert_off_alert();

    cs_item = csrng_item::type_id::create("illegal_cmd");
    cs_item.acmd = csrng_pkg::GENU;
    cs_item.clen = 'h2;
    cs_item.flags = MuBi4True;
    cs_item.glen = 'h2;
    cs_item.cmd_data_q.push_back(32'h11112222);
    cs_item.cmd_data_q.push_back(32'h33334444);

    send_cmd_req(SW_APP, cs_item, .await_response(1'b0));
    cfg.m_alert_agent_cfgs["recov_alert"].vif.wait_ack_complete();
    csr_wr(.ptr(ral.recov_alert_sts), .value(32'b0));
    csr_wr(.ptr(ral.intr_state), .value(1 << CmdReqDone));
    cfg.clk_rst_vif.wait_clks(20);

    cs_item = csrng_item::type_id::create("legal_ins_cmd");
    cs_item.acmd = csrng_pkg::INS;
    cs_item.clen = 'h0;
    cs_item.flags = MuBi4True;
    cs_item.glen = 'h0;
    send_cmd_req(SW_APP, cs_item, .await_response(1'b0));
    wait_cmd_req_done_short("legal instantiate");

    cs_item = csrng_item::type_id::create("legal_uni_cmd");
    cs_item.acmd = csrng_pkg::UNI;
    cs_item.clen = 'h0;
    cs_item.flags = MuBi4True;
    cs_item.glen = 'h0;
    send_cmd_req(SW_APP, cs_item, .await_response(1'b0));
    wait_cmd_req_done_short("legal uninstantiate");

    cfg.csrng_assert_vif.assert_on_alert();
  endtask
endclass
SVEOF

  cat > hw/ip/csrng/dv/tests/csrng_cmd_stage_hang_test.sv <<'SVEOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class csrng_cmd_stage_hang_test extends csrng_base_test;
  `uvm_component_utils(csrng_cmd_stage_hang_test)
  `uvm_component_new

  function void configure_env();
    super.configure_env();
    cfg.en_scb = 0;
    cfg.otp_en_cs_sw_app_read_pct = 100;
    cfg.otp_en_cs_sw_app_read_inval_pct = 0;
    cfg.lc_hw_debug_en_pct = 0;
    cfg.regwen_pct = 100;
    cfg.enable_pct = 100;
    cfg.sw_app_enable_pct = 100;
    cfg.read_int_state_pct = 0;
    cfg.check_int_state_pct = 0;
    cfg.use_invalid_mubi = 0;
    `DV_CHECK_RANDOMIZE_FATAL(cfg)
  endfunction
endclass
SVEOF

  python - <<'PY'
from pathlib import Path

def add_after(path_str: str, marker: str, addition: str) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if addition.strip() in text:
        return
    if marker not in text:
        raise SystemExit(f"marker not found in {path_str}")
    path.write_text(text.replace(marker, marker + addition), encoding="utf-8")

add_after(
    "hw/ip/csrng/dv/env/seq_lib/csrng_vseq_list.sv",
    '`include "csrng_regwen_vseq.sv"\n',
    '`include "csrng_cmd_stage_hang_vseq.sv"\n',
)
add_after(
    "hw/ip/csrng/dv/tests/csrng_test_pkg.sv",
    '  `include "csrng_regwen_test.sv"\n',
    '  `include "csrng_cmd_stage_hang_test.sv"\n',
)
add_after(
    "hw/ip/csrng/dv/env/csrng_env.core",
    '      - seq_lib/csrng_regwen_vseq.sv: {is_include_file: true}\n',
    '      - seq_lib/csrng_cmd_stage_hang_vseq.sv: {is_include_file: true}\n',
)
add_after(
    "hw/ip/csrng/dv/tests/csrng_test.core",
    '      - csrng_regwen_test.sv: {is_include_file: true}\n',
    '      - csrng_cmd_stage_hang_test.sv: {is_include_file: true}\n',
)

sim_cfg = Path("hw/ip/csrng/dv/csrng_sim_cfg.hjson")
text = sim_cfg.read_text(encoding="utf-8")
if "name: csrng_cmd_stage_hang" not in text:
    marker = "\n    {\n      name: csrng_regwen\n      uvm_test: csrng_regwen_test\n      uvm_test_seq: csrng_regwen_vseq\n    }\n"
    addition = "\n    {\n      name: csrng_cmd_stage_hang\n      uvm_test: csrng_cmd_stage_hang_test\n      uvm_test_seq: csrng_cmd_stage_hang_vseq\n    }\n"
    if marker not in text:
        raise SystemExit("csrng_regwen block not found in csrng_sim_cfg.hjson")
    sim_cfg.write_text(text.replace(marker, marker + addition), encoding="utf-8")
PY
}

if ! inject_test; then
  emit_result "FAIL"
  exit 1
