from pathlib import Path
import sys


def replace_once(path_str: str, old: str, new: str, alternate: str | None = None) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if new in text:
        return
    if old not in text:
        if alternate and alternate in text:
            return
        raise RuntimeError(f"unable to patch {path}: missing anchor")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def insert_after(path_str: str, anchor: str, insertion: str, alternate: str | None = None) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if insertion.strip() in text:
        return
    if alternate and alternate in text:
        return
    if anchor not in text:
        raise RuntimeError(f"unable to patch {path}: missing insertion anchor")
    path.write_text(text.replace(anchor, anchor + insertion, 1), encoding="utf-8")


def write_file(path_str: str, content: str) -> None:
    path = Path(path_str)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


