    .mbx_sys_abort_o(ob_mbx_sys_abort),
    .mbx_ready_update_o(ob_mbx_ready_update),
    .mbx_ready_o(ob_mbx_ready),
    .mbx_irq_ready_o(ob_mbx_irq_ready),
    .mbx_irq_abort_o(ob_mbx_irq_abort),
    .mbx_state_error_o(ob_mbx_state_error)
  );

  always #5 clk = ~clk;

  task automatic step;
    begin
      @(posedge clk);
      #1;
    end
  endtask

  task automatic fail(input string msg);
    begin
      $display("TB_STATUS: FAIL: %s", msg);
      $finish;
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_ni = 1'b0;

    ib_mbx_range_valid = 1'b0;
    ib_hostif_abort_ack = 1'b0;
    ib_mbx_error_set = 1'b0;
    ib_sysif_control_abort_set = 1'b0;
    ib_sys_read_all = 1'b0;
    ib_writer_close_mbx = 1'b0;
    ib_writer_last_word_written = 1'b0;
    ib_writer_write_valid = 1'b0;

    ob_mbx_range_valid = 1'b0;
    ob_hostif_abort_ack = 1'b0;
    ob_mbx_error_set = 1'b0;
    ob_sysif_control_abort_set = 1'b0;
    ob_sys_read_all = 1'b0;
    ob_writer_close_mbx = 1'b0;
    ob_writer_last_word_written = 1'b0;
    ob_writer_write_valid = 1'b0;

    repeat (2) step();
    rst_ni = 1'b1;
    ib_mbx_range_valid = 1'b1;
    ob_mbx_range_valid = 1'b1;
    step();

    if (ib_mbx_empty !== 1'b1 || ib_mbx_write !== 1'b0 || ib_mbx_sys_abort !== 1'b0) begin
      fail("Inbound FSM did not start in idle state");
    end
    if (ob_mbx_empty !== 1'b1 || ob_mbx_read !== 1'b0) begin
      fail("Outbound FSM did not start in idle state");
    end

    ib_writer_write_valid = 1'b1;
    step();
    ib_writer_write_valid = 1'b0;

    if (ib_mbx_write !== 1'b1 || ib_mbx_empty !== 1'b0) begin
      fail("Inbound FSM did not enter write state");
    end

    ib_hostif_abort_ack = 1'b1;
    step();
    if (ib_mbx_empty !== 1'b1 || ib_mbx_write !== 1'b0 || ib_mbx_sys_abort !== 1'b0) begin
      fail("Inbound host abort acknowledge did not reset the FSM");
    end
    ib_hostif_abort_ack = 1'b0;
    step();

    ib_writer_write_valid = 1'b1;
    step();
    ib_writer_write_valid = 1'b0;
    if (ib_mbx_write !== 1'b1) begin
      fail("Inbound FSM did not recover after host abort acknowledge");
    end

    ob_writer_close_mbx = 1'b1;
    step();
    if (ob_mbx_read !== 1'b1) begin
      fail("Outbound FSM did not enter read state");
    end
    ob_writer_close_mbx = 1'b0;

    ob_hostif_abort_ack = 1'b1;
    step();
    if (ob_mbx_empty !== 1'b1 || ob_mbx_read !== 1'b0) begin
      fail("Outbound host abort acknowledge did not return the FSM to idle");
    end
    if (ob_mbx_ready_update !== 1'b1 || ob_mbx_ready !== 1'b0) begin
      fail("Outbound host abort acknowledge did not clear ready");
    end
    ob_hostif_abort_ack = 1'b0;
    step();

    ob_writer_close_mbx = 1'b1;
    step();
    if (ob_mbx_read !== 1'b1) begin
      fail("Outbound FSM did not recover after host abort acknowledge");
    end

    $display("TB_STATUS: PASS");
    $finish;
  end
endmodule
