    csr_spinwait(.ptr(ral.main_sm_state), .exp_data(edn_pkg::Idle), .backdoor(1'b1));
    cfg.clk_rst_vif.wait_n_clks(2);

    rescmd_depth_path = {cfg.edn_vif.core_path, ".sfifo_rescmd_depth"};
    gencmd_depth_path = {cfg.edn_vif.core_path, ".sfifo_gencmd_depth"};
    cmd_fifo_cnt_path = {cfg.edn_vif.core_path, ".cmd_fifo_cnt_q"};

    `DV_CHECK(uvm_hdl_read(rescmd_depth_path, val))
    depth_val = val[3:0];
    `DV_CHECK_EQ_FATAL(depth_val, 0,
                       $sformatf("Expected reseed FIFO depth to clear after disable, got 0x%0h",
                                 depth_val))
    `DV_CHECK(uvm_hdl_read(gencmd_depth_path, val))
    depth_val = val[3:0];
    `DV_CHECK_EQ_FATAL(depth_val, 0,
                       $sformatf("Expected generate FIFO depth to clear after disable, got 0x%0h",
                                 depth_val))
    `DV_CHECK(uvm_hdl_read(cmd_fifo_cnt_path, val))
    depth_val = val[3:0];
    `DV_CHECK_EQ_FATAL(depth_val, 0,
                       $sformatf("Expected cmd_fifo_cnt_q to clear after disable, got 0x%0h",
                                 depth_val))
  endtask

  task randomly_disable_edn();
""",
    "task check_auto_cmd_fifos_cleared();",
)

path = Path(vseq_path)
text = path.read_text()
old_base = """        // Wait for EDN to come out of reset.
        wait(cfg.clk_rst_vif.rst_n);
        // Disable EDN after a random number of cycles or in a random state.
        randomly_disable_edn();
        // Abort any open SW commands and wait for CSR accesses to complete, as simply killing their
        // thread would create problems later due to unterminated accesses.
        cfg.abort_sw_cmd = 1;
"""
old_fix = """        // Wait for EDN to come out of reset.
        wait(cfg.clk_rst_vif.rst_n);
        // Wait for the EDN to be enabled.
        wait(cfg.base_vseq_edn_enabled);
        // Disable EDN after a random number of cycles or in a random state.
        randomly_disable_edn();
        // Abort any open SW commands and wait for CSR accesses to complete, as simply killing their
        // thread would create problems later due to unterminated accesses.
        cfg.abort_sw_cmd = 1;
"""
new_common = """        // Wait for EDN to come out of reset.
        wait(cfg.clk_rst_vif.rst_n);
        // Wait for the EDN to be enabled.
        wait(cfg.base_vseq_edn_enabled);
        // Disable EDN after a random number of cycles or in a random state.
        randomly_disable_edn();
        check_auto_cmd_fifos_cleared();
        // Abort any open SW commands and wait for CSR accesses to complete, as simply killing their
        // thread would create problems later due to unterminated accesses.
        cfg.abort_sw_cmd = 1;
"""
if "check_auto_cmd_fifos_cleared();" not in text:
    raise SystemExit(f"[ERROR] helper insertion failed in {vseq_path}")
if new_common not in text:
    if old_fix in text:
        text = text.replace(old_fix, new_common, 1)
    elif old_base in text:
        text = text.replace(old_base, new_common, 1)
    else:
        raise SystemExit(f"[ERROR] pre_start block not found in {vseq_path}")
    path.write_text(text)
    print(f"[INFO] {path.name}: pre_start block updated")
else:
    print(f"[INFO] {path.name}: pre_start block already updated")

remove_once(
    vseq_path,
    """        // TODO: Remove the following lines resetting the FIFOs based on decision in #19653.
        // Reset cmd FIFO to prevent FIFO from overflowing after re-enabling EDN.
        csr_wr(.ptr(ral.ctrl.cmd_fifo_rst), .value(MuBi4True));
        csr_wr(.ptr(ral.ctrl.cmd_fifo_rst), .value(MuBi4False));
""",
)
PY
}

