    -i edn_disable_auto_req_mode \
    -t vcs \
    --local -mp 1 \
    --fixed-seed 1 --build-seed 1 \
    --no-rerun \
    --build-timeout-mins 25 \
    --run-timeout-mins 5 \
    --scratch-root "$SCRATCH_ROOT" \
    --proj-root /home/opentitan \
    --branch tb_edn_fifo_clear
} 2>&1 | tee "$RUN_LOG"
rc=${PIPESTATUS[0]}

if [ "$rc" -eq 0 ]; then
  emit_result "PASS"
else
  emit_result "FAIL"
fi
exit "$rc"

