// SPDX-License-Identifier: Apache-2.0

class edn_boot_to_sw_vseq extends edn_base_vseq;
  `uvm_object_utils(edn_boot_to_sw_vseq)
  `uvm_object_new

  localparam int BootDoneTimeoutClks = 200;
  localparam int SwModeTimeoutClks = 200;
  localparam int CmdReadyTimeoutClks = 50;

  task automatic wait_for_main_sm_state(state_e exp_state, int timeout_clks, string state_name);
    string state_path;
    uvm_hdl_data_t val;
    bit reached;

    state_path = cfg.edn_vif.sm_err_path("edn_main_sm");
    reached = 1'b0;

    repeat (timeout_clks) begin
      `DV_CHECK(uvm_hdl_read(state_path, val))
      if (state_e'(val) == exp_state) begin
        reached = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end

    `DV_CHECK_FATAL(reached,
                    $sformatf("Timed out waiting for %s, last main_sm_state=0x%0h",
                              state_name, val))
  endtask

  task automatic wait_for_cmd_ready();
    bit [TL_DW-1:0] sw_cmd_sts;
    bit reached;

    reached = 1'b0;
    repeat (CmdReadyTimeoutClks) begin
      csr_rd(.ptr(ral.sw_cmd_sts), .value(sw_cmd_sts), .backdoor(1'b1));
      if (sw_cmd_sts[0]) begin
        reached = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end

    `DV_CHECK_FATAL(reached, "Timed out waiting for SW_CMD_STS.CMD_RDY after boot exit")
  endtask

  task body();
    super.body();

    wait_for_main_sm_state(BootDone, BootDoneTimeoutClks, "BootDone");

    ral.ctrl.boot_req_mode.set(MuBi4False);
    csr_update(.csr(ral.ctrl));

    wait_for_main_sm_state(SWPortMode, SwModeTimeoutClks, "SWPortMode");
    wait_for_cmd_ready();

    wr_cmd(.cmd_type(edn_env_pkg::Sw),
           .acmd(csrng_pkg::INS),
           .clen(0),
           .flags(MuBi4False),
           .glen(1),
           .mode(edn_env_pkg::SwMode));

    wr_cmd(.cmd_type(edn_env_pkg::Sw),
           .acmd(csrng_pkg::UNI),
           .clen(0),
           .flags(MuBi4False),
           .glen(0),
           .mode(edn_env_pkg::SwMode));
  endtask

endclass
