#!/bin/bash
set -euo pipefail

cd /home/opentitan || exit 1

if [[ -f /home/opentitan/.tool_paths.sh ]]; then
  source /home/opentitan/.tool_paths.sh
fi

TEST_NAME="i2c_sda_interference_repro"
SCRATCH_ROOT="/home/opentitan/.tb_${TEST_NAME}"
SEQ_FILE="/home/opentitan/hw/ip/i2c/dv/env/seq_lib/i2c_host_sda_interference_repro_vseq.sv"
VSEQ_LIST="/home/opentitan/hw/ip/i2c/dv/env/seq_lib/i2c_vseq_list.sv"
ENV_CORE="/home/opentitan/hw/ip/i2c/dv/env/i2c_env.core"
RUN_LOG="${SCRATCH_ROOT}/dvsim.log"
RESULT_RECORDED=0

echo "HWE_BENCH_RESULTS_START"
cleanup() {
  if [[ "${RESULT_RECORDED}" -eq 0 ]]; then
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
}
trap cleanup EXIT

rm -rf "${SCRATCH_ROOT}"
mkdir -p "${SCRATCH_ROOT}"

cat > "${SEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class i2c_host_sda_interference_repro_vseq extends i2c_base_vseq;
  `uvm_object_utils(i2c_host_sda_interference_repro_vseq)
  `uvm_object_new

  virtual task pre_start();
    super.pre_start();
    cfg.seq_cfg.en_sda_unstable = 1'b0;
    cfg.seq_cfg.en_sda_interference = 1'b0;
    cfg.seq_cfg.en_scl_interference = 1'b0;
  endtask : pre_start

  virtual task body();
    timing_cfg_t fixed_timing_cfg;
    logic prev_sda_en;
    logic cur_sda_en;
    bit sda_interference_seen;
    bit rxempty;
    bit hostidle;
    bit got_rx_byte;

    initialization(.mode(Host));

    sda_interference_seen = 1'b0;
    got_rx_byte = 1'b0;
    hostidle = 1'b0;
    rxempty = 1'b1;

    rw_bit = 1'b1;
    addr = 10'h000;
    e_timeout = 1'b0;
    t_timeout = 31'd0;
    thigh = 16'd2;
    tlow = 16'd7;
    t_r = 16'd4;
    t_f = 16'd1;
    thd_sta = 16'd1;
    tsu_sta = 16'd5;
    tsu_sto = 16'd4;
    tsu_dat = 16'd1;
    thd_dat = 16'd1;
    t_buf = 16'd2;

    fixed_timing_cfg.enbTimeOut = e_timeout;
    fixed_timing_cfg.tTimeOut = t_timeout;
    fixed_timing_cfg.tSetupStart = t_r + tsu_sta;
    fixed_timing_cfg.tHoldStart = t_f + thd_sta;
    fixed_timing_cfg.tClockStart = thd_dat;
    fixed_timing_cfg.tClockLow = tlow - t_r - tsu_dat - thd_dat;
    fixed_timing_cfg.tSetupBit = t_r + tsu_dat;
    fixed_timing_cfg.tClockPulse = t_r + thigh + t_f;
    fixed_timing_cfg.tHoldBit = t_f + thd_dat;
    fixed_timing_cfg.tClockStop = t_f + tlow - thd_dat;
    fixed_timing_cfg.tSetupStop = t_r + tsu_sto;
    fixed_timing_cfg.tHoldStop = t_r + t_buf - tsu_sta;
    fixed_timing_cfg.tStretchHostClock = 0;
    fixed_timing_cfg.tSdaUnstable = 0;
    fixed_timing_cfg.tSclInterference = 0;
    fixed_timing_cfg.tSdaInterference = 0;

    ral.timing0.tlow.set(tlow);
    ral.timing0.thigh.set(thigh);
    csr_update(.csr(ral.timing0));
    ral.timing1.t_f.set(t_f);
    ral.timing1.t_r.set(t_r);
    csr_update(.csr(ral.timing1));
    ral.timing2.thd_sta.set(thd_sta);
    ral.timing2.tsu_sta.set(tsu_sta);
    csr_update(.csr(ral.timing2));
    ral.timing3.thd_dat.set(thd_dat);
    ral.timing3.tsu_dat.set(tsu_dat);
    csr_update(.csr(ral.timing3));
    ral.timing4.tsu_sto.set(tsu_sto);
    ral.timing4.t_buf.set(t_buf);
    csr_update(.csr(ral.timing4));
    ral.timeout_ctrl.en.set(e_timeout);
    ral.timeout_ctrl.val.set(t_timeout);
    csr_update(.csr(ral.timeout_ctrl));
    cfg.m_i2c_agent_cfg.timing_cfg = fixed_timing_cfg;

    ral.fifo_ctrl.rxrst.set(1'b0);
    ral.fifo_ctrl.fmtrst.set(1'b0);
    ral.fifo_ctrl.acqrst.set(1'b0);
    ral.fifo_ctrl.txrst.set(1'b0);
    ral.fifo_ctrl.rxilvl.set(3'h0);
    ral.fifo_ctrl.fmtilvl.set(2'h0);
    csr_update(.csr(ral.fifo_ctrl));

    fork : monitor_irq
      forever begin
        @(posedge cfg.clk_rst_vif.clk);
        if (cfg.intr_vif.pins[SdaInference]) begin
          sda_interference_seen = 1'b1;
          `uvm_info(`gfn, "Observed unexpected sda_interference interrupt", UVM_LOW)
        end
      end
    join_none

    if (!uvm_hdl_read("tb.cio_sda_en_o", prev_sda_en)) begin
      `uvm_fatal(`gfn, "Failed to read tb.cio_sda_en_o")
    end

    fork : inject_slow_rise
      begin
        forever begin
          @(posedge cfg.clk_rst_vif.clk);
          if (!uvm_hdl_read("tb.cio_sda_en_o", cur_sda_en)) begin
            `uvm_fatal(`gfn, "Failed to read tb.cio_sda_en_o")
          end
          if (prev_sda_en && !cur_sda_en) begin
            if (!uvm_hdl_force("tb.cio_sda_i", 1'b0)) begin
              `uvm_fatal(`gfn, "Failed to force tb.cio_sda_i")
            end
            cfg.clk_rst_vif.wait_clks(3);
            if (!uvm_hdl_release("tb.cio_sda_i")) begin
              `uvm_fatal(`gfn, "Failed to release tb.cio_sda_i")
            end
            break;
          end
          prev_sda_en = cur_sda_en;
        end
      end
    join_none

    csr_spinwait(.ptr(ral.status.fmtfull), .exp_data(1'b0));
    ral.fdata.fbyte.set(8'h01);
    ral.fdata.start.set(1'b1);
    ral.fdata.stop.set(1'b0);
    ral.fdata.read.set(1'b0);
    ral.fdata.rcont.set(1'b0);
    ral.fdata.nakok.set(1'b0);
    csr_update(.csr(ral.fdata));
    cfg.clk_rst_vif.wait_clks(1);

    csr_spinwait(.ptr(ral.status.fmtfull), .exp_data(1'b0));
    ral.fdata.fbyte.set(8'd1);
    ral.fdata.start.set(1'b0);
    ral.fdata.stop.set(1'b1);
    ral.fdata.read.set(1'b1);
    ral.fdata.rcont.set(1'b0);
    ral.fdata.nakok.set(1'b0);
    csr_update(.csr(ral.fdata));
    cfg.clk_rst_vif.wait_clks(1);

    for (int i = 0; i < 2000; i++) begin
      if (sda_interference_seen) begin
        `uvm_fatal(`gfn, "Unexpected sda_interference interrupt during clean read transaction")
      end
      csr_rd(.ptr(ral.status.rxempty), .value(rxempty));
      if (!rxempty) begin
        got_rx_byte = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    `DV_CHECK_FATAL(got_rx_byte, "Timed out waiting for read data")

    csr_rd(.ptr(ral.rdata), .value(rd_data));

    for (int i = 0; i < 2000; i++) begin
      if (sda_interference_seen) begin
        `uvm_fatal(`gfn, "Unexpected sda_interference interrupt during clean read transaction")
      end
      csr_rd(.ptr(ral.status.hostidle), .value(hostidle));
      csr_rd(.ptr(ral.status.rxempty), .value(rxempty));
      if (hostidle && rxempty) begin
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end

    disable monitor_irq;
    disable inject_slow_rise;

    `DV_CHECK_EQ_FATAL(sda_interference_seen, 1'b0)
    `DV_CHECK_EQ_FATAL(hostidle, 1'b1)
    `DV_CHECK_EQ_FATAL(rxempty, 1'b1)
  endtask : body

endclass : i2c_host_sda_interference_repro_vseq
EOF

