#!/bin/bash
cd /home/opentitan
set -euo pipefail

TEST_NAME="flash_phy_core_ctrl_erase_lockup"
TB_DIR="/home/opentitan/.tb_flash_phy_core_ctrl_erase_lockup"
BUILD_DIR="$TB_DIR/build"
RUN_LOG="$TB_DIR/fusesoc_run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/flash_phy_core_lockup_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:flash_phy_core_lockup_tb:0.1"
description: "Minimal flash_phy_core controller erase lockup reproducer"

filesets:
  files_tb:
    depend:
      - lowrisc:ip:flash_ctrl:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  default: &default_target
    toplevel: flash_phy_core_lockup_tb
    filesets:
      - files_tb

  sim:
    <<: *default_target
    default_tool: vcs
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module flash_phy_core_lockup_tb;
  import flash_phy_pkg::*;
  import flash_ctrl_pkg::flash_part_e;
  import flash_ctrl_pkg::flash_prog_e;
  import flash_ctrl_pkg::FlashPartData;
  import flash_ctrl_pkg::FlashProgNormal;
  import prim_mubi_pkg::mubi4_t;
  import prim_mubi_pkg::MuBi4False;

  logic clk;
  logic rst_ni;

  logic host_req_i;
  logic host_scramble_en_i;
  logic host_ecc_en_i;
  logic [BusBankAddrW-1:0] host_addr_i;
  logic req_i;
  logic scramble_en_i;
  logic ecc_en_i;
  logic he_en_i;
  logic rd_i;
  logic prog_i;
  logic pg_erase_i;
  logic bk_erase_i;
  logic erase_suspend_req_i;
  flash_part_e part_i;
  logic [InfoTypesWidth-1:0] info_sel_i;
  logic [BusBankAddrW-1:0] addr_i;
  logic [BusFullWidth-1:0] prog_data_i;
  logic prog_last_i;
  flash_prog_e prog_type_i;
  logic [KeySize-1:0] addr_key_i;
  logic [KeySize-1:0] data_key_i;
  logic [KeySize-1:0] rand_addr_key_i;
  logic [KeySize-1:0] rand_data_key_i;
  logic rd_buf_en_i;
  mubi4_t flash_disable_i;
  flash_phy_prim_flash_rsp_t prim_flash_rsp_i;
  flash_phy_prim_flash_req_t prim_flash_req_o;
  logic host_req_rdy_o;
  logic host_req_done_o;
  logic rd_done_o;
  logic prog_done_o;
  logic erase_done_o;
  logic [BusFullWidth-1:0] rd_data_o;
  logic rd_err_o;
  logic ecc_single_err_o;
  logic [BusBankAddrW-1:0] ecc_addr_o;
  logic fsm_err_o;
  logic prog_intg_err_o;
  logic relbl_ecc_err_o;
  logic intg_ecc_err_o;
  logic spurious_ack_o;
  logic arb_err_o;
  logic host_gnt_err_o;

  logic macro_req;
  integer done_countdown;
  bit saw_macro_req;
  bit saw_erase_done;

  flash_phy_core dut (
    .clk_i(clk),
    .rst_ni,
    .host_req_i,
    .host_scramble_en_i,
    .host_ecc_en_i,
    .host_addr_i,
    .req_i,
    .scramble_en_i,
    .ecc_en_i,
    .he_en_i,
    .rd_i,
    .prog_i,
    .pg_erase_i,
    .bk_erase_i,
    .erase_suspend_req_i,
    .part_i,
    .info_sel_i,
    .addr_i,
    .prog_data_i,
    .prog_last_i,
    .prog_type_i,
    .addr_key_i,
    .data_key_i,
    .rand_addr_key_i,
    .rand_data_key_i,
    .rd_buf_en_i,
    .flash_disable_i,
    .prim_flash_rsp_i,
    .prim_flash_req_o,
    .host_req_rdy_o,
    .host_req_done_o,
    .rd_done_o,
    .prog_done_o,
    .erase_done_o,
    .rd_data_o,
    .rd_err_o,
    .ecc_single_err_o,
    .ecc_addr_o,
    .fsm_err_o,
    .prog_intg_err_o,
    .relbl_ecc_err_o,
    .intg_ecc_err_o,
    .spurious_ack_o,
    .arb_err_o,
    .host_gnt_err_o
  );

  defparam dut.u_state_regs.EnableAlertTriggerSVA = 0;
  defparam dut.gen_prog_data.u_prog.u_state_regs.EnableAlertTriggerSVA = 0;

  assign macro_req = prim_flash_req_o.rd_req |
                     prim_flash_req_o.prog_req |
                     prim_flash_req_o.pg_erase_req |
                     prim_flash_req_o.bk_erase_req |
                     prim_flash_req_o.erase_suspend_req;

  always #5 clk = ~clk;

  always_comb begin
    prim_flash_rsp_i.ack = macro_req;
    prim_flash_rsp_i.rdata = '1;
  end

  always_ff @(posedge clk or negedge rst_ni) begin
    if (!rst_ni) begin
      prim_flash_rsp_i.done <= 1'b0;
      done_countdown <= -1;
    end else begin
      prim_flash_rsp_i.done <= 1'b0;
      if (macro_req && done_countdown < 0) begin
        done_countdown <= 2;
      end else if (done_countdown == 0) begin
        prim_flash_rsp_i.done <= 1'b1;
        done_countdown <= -1;
      end else if (done_countdown > 0) begin
        done_countdown <= done_countdown - 1;
      end
    end
  end

  initial begin
    clk = 1'b0;
    rst_ni = 1'b0;
    host_req_i = 1'b0;
    host_scramble_en_i = 1'b0;
    host_ecc_en_i = 1'b0;
    host_addr_i = '0;
    req_i = 1'b0;
    scramble_en_i = 1'b0;
    ecc_en_i = 1'b0;
    he_en_i = 1'b0;
    rd_i = 1'b0;
    prog_i = 1'b0;
    pg_erase_i = 1'b0;
    bk_erase_i = 1'b0;
    erase_suspend_req_i = 1'b0;
    part_i = FlashPartData;
    info_sel_i = '0;
    addr_i = '0;
    prog_data_i = '0;
    prog_last_i = 1'b1;
    prog_type_i = FlashProgNormal;
    addr_key_i = '0;
    data_key_i = '0;
    rand_addr_key_i = '0;
    rand_data_key_i = '0;
    rd_buf_en_i = 1'b0;
    flash_disable_i = MuBi4False;
    saw_macro_req = 1'b0;
    saw_erase_done = 1'b0;

    repeat (5) @(posedge clk);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk);

    req_i = 1'b1;
    pg_erase_i = 1'b1;

    repeat (40) begin
      @(posedge clk);
      if (prim_flash_req_o.pg_erase_req) begin
        saw_macro_req = 1'b1;
      end
      if (erase_done_o) begin
        saw_erase_done = 1'b1;
        req_i = 1'b0;
        pg_erase_i = 1'b0;
      end
    end

    if (!saw_macro_req) begin
      $display("TB_FAIL: controller erase request never reached the flash macro");
      $fatal(1);
    end

    if (!saw_erase_done) begin
      $display("TB_FAIL: controller erase request did not complete");
      $fatal(1);
    end

    if (fsm_err_o || arb_err_o || host_gnt_err_o || prog_intg_err_o ||
        relbl_ecc_err_o || intg_ecc_err_o || spurious_ack_o) begin
      $display("TB_FAIL: unexpected internal error output asserted");
      $fatal(1);
    end

    $display("TB_PASS: controller erase completed when flash ack behaved like ready");
    $finish;
  end
endmodule
EOF

