#!/bin/bash
cd /home/opentitan || exit 1
set -uo pipefail

TEST_NAME="adc_ctrl_intr_cdc"
TB_DIR="/home/opentitan/.tb_adc_ctrl_intr_sync"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
PASS_SENTINEL="${TB_DIR}/sim.pass"
FAIL_SENTINEL="${TB_DIR}/sim.fail"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

cat > "${TB_DIR}/prim_flop.sv" <<'SV'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input logic clk_i,
  input logic rst_ni,
  input logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule
SV

cat > "${TB_DIR}/tb.sv" <<'SV'
module tb;
  import adc_ctrl_reg_pkg::*;

  logic clk_aon_i = 0;
  logic clk_i = 0;
  logic rst_aon_ni = 0;
  logic rst_ni = 0;
  logic gate_clk_i = 0;
  logic [NumAdcFilter-1:0] aon_filter_match_i = '0;
  logic [8:0] cfg_intr_en_i = '0;
  logic cfg_oneshot_done_i = 1'b0;
  adc_ctrl_reg2hw_intr_state_reg_t intr_state_i;
  adc_ctrl_reg2hw_intr_enable_reg_t intr_enable_i;
  adc_ctrl_reg2hw_intr_test_reg_t intr_test_i;
  adc_ctrl_hw2reg_intr_state_reg_t intr_state_o;
  adc_ctrl_hw2reg_adc_intr_status_reg_t adc_intr_status_o;
  logic intr_debug_cable_o;
  logic status_seen;

  always #5 clk_aon_i = ~clk_aon_i;

  always begin
    #2;
    if (!gate_clk_i) begin
      clk_i = ~clk_i;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      intr_state_i.q <= 1'b0;
      status_seen <= 1'b0;
    end else begin
      if (intr_state_o.de) begin
        intr_state_i.q <= intr_state_o.d;
      end
      if (adc_intr_status_o.cc_sink_det.de && adc_intr_status_o.cc_sink_det.d) begin
        status_seen <= 1'b1;
      end
    end
  end

  task automatic send_filter_pulse();
    begin
      @(negedge clk_aon_i);
      aon_filter_match_i[0] = 1'b1;
      @(negedge clk_aon_i);
      aon_filter_match_i[0] = 1'b0;
    end
  endtask

  initial begin
    intr_enable_i.q = 1'b1;
    intr_test_i.q = 1'b0;
    intr_test_i.qe = 1'b0;
    cfg_intr_en_i[0] = 1'b1;

    repeat (4) @(posedge clk_aon_i);
    rst_aon_ni = 1'b1;
    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (4) @(posedge clk_i);

    @(negedge clk_i);
    gate_clk_i = 1'b1;
    clk_i = 1'b0;

    repeat (2) @(posedge clk_aon_i);
    send_filter_pulse();
    repeat (1) @(posedge clk_aon_i);
    send_filter_pulse();
    repeat (4) @(posedge clk_aon_i);

    gate_clk_i = 1'b0;
    repeat (20) @(posedge clk_i);

    $display("TB_RESULT status_seen=%0d intr_state=%0d intr_o=%0d", status_seen, intr_state_i.q,
             intr_debug_cable_o);
    if (!status_seen || !intr_state_i.q) begin
      void'($system("touch /home/opentitan/.tb_adc_ctrl_intr_sync/sim.fail"));
      $display("TB_FAIL");
      $finish;
    end

    void'($system("touch /home/opentitan/.tb_adc_ctrl_intr_sync/sim.pass"));
    $display("TB_PASS");
    $finish;
  end

  adc_ctrl_intr dut (
    .clk_aon_i,
    .rst_aon_ni,
    .clk_i,
    .rst_ni,
    .aon_filter_match_i,
    .cfg_intr_en_i,
    .cfg_oneshot_done_i,
    .intr_state_i,
    .intr_enable_i,
    .intr_test_i,
    .intr_state_o,
    .adc_intr_status_o,
    .intr_debug_cable_o
  );
endmodule
SV

