// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class rstmgr_non_aon_por_vseq extends rstmgr_base_vseq;
  `uvm_object_utils(rstmgr_non_aon_por_vseq)

  `uvm_object_new

  localparam int NonAonDomain = rstmgr_pkg::Domain0Sel;
  localparam int AonSettleClks = 4;
  localparam int RestartTimeoutClks = 40;

  task stop_fast_clocks();
    cfg.clk_rst_vif.stop_clk();
    cfg.io_clk_rst_vif.stop_clk();
    cfg.io_div2_clk_rst_vif.stop_clk();
    cfg.io_div4_clk_rst_vif.stop_clk();
    cfg.main_clk_rst_vif.stop_clk();
    cfg.usb_clk_rst_vif.stop_clk();
  endtask

  task start_fast_clocks();
    fork
      cfg.clk_rst_vif.start_clk();
      cfg.io_clk_rst_vif.start_clk();
      cfg.io_div2_clk_rst_vif.start_clk();
      cfg.io_div4_clk_rst_vif.start_clk();
      cfg.main_clk_rst_vif.start_clk();
      cfg.usb_clk_rst_vif.start_clk();
    join
  endtask

  task body();
    cfg.pwrmgr_rstmgr_sva_vif.disable_sva = 1'b1;
    cfg.clk_rst_vif.wait_clks(5);
    cfg.aon_clk_rst_vif.wait_clks(2);

    `DV_CHECK_EQ(cfg.rstmgr_vif.por_n[NonAonDomain], 1'b1)
    `DV_CHECK_EQ(cfg.rstmgr_vif.resets_o.rst_por_aon_n[NonAonDomain], 1'b1)
    `DV_CHECK_EQ(cfg.rstmgr_vif.pwr_o.rst_lc_src_n[NonAonDomain], 1'b1)
    `DV_CHECK_EQ(cfg.rstmgr_vif.pwr_o.rst_sys_src_n[NonAonDomain], 1'b1)

    `uvm_info(`gfn, "Drive non-AON POR low while fast clocks are stopped.", UVM_MEDIUM)
    stop_fast_clocks();
    cfg.rstmgr_vif.por_n[NonAonDomain] = 1'b0;
    cfg.aon_clk_rst_vif.wait_clks(AonSettleClks);

    `DV_CHECK_EQ(cfg.rstmgr_vif.resets_o.rst_por_aon_n[NonAonDomain], 1'b0,
                 "Expected non-AON POR reset to assert")
    `DV_CHECK_EQ(cfg.rstmgr_vif.pwr_o.rst_lc_src_n[NonAonDomain], 1'b0,
                 "Expected lc source reset to assert without clk_i")
    `DV_CHECK_EQ(cfg.rstmgr_vif.pwr_o.rst_sys_src_n[NonAonDomain], 1'b0,
                 "Expected sys source reset to assert without clk_i")

    `uvm_info(`gfn, "Release non-AON POR and restart fast clocks.", UVM_MEDIUM)
    cfg.rstmgr_vif.por_n[NonAonDomain] = 1'b1;
    cfg.aon_clk_rst_vif.wait_clks(AonSettleClks);
    start_fast_clocks();
    `DV_SPINWAIT_EXIT(wait (cfg.rstmgr_vif.pwr_o.rst_lc_src_n[NonAonDomain] == 1'b1 &&
                            cfg.rstmgr_vif.pwr_o.rst_sys_src_n[NonAonDomain] == 1'b1);,
                      cfg.clk_rst_vif.wait_clks(RestartTimeoutClks);,
                      "timeout waiting for lc/sys reset release after POR recovery")

    `DV_CHECK_EQ(cfg.rstmgr_vif.resets_o.rst_por_aon_n[NonAonDomain], 1'b1)
    `DV_CHECK_EQ(cfg.rstmgr_vif.pwr_o.rst_lc_src_n[NonAonDomain], 1'b1)
    `DV_CHECK_EQ(cfg.rstmgr_vif.pwr_o.rst_sys_src_n[NonAonDomain], 1'b1)
    cfg.pwrmgr_rstmgr_sva_vif.disable_sva = 1'b0;
  endtask
endclass
EOF

