#!/bin/bash
set -uo pipefail

cd /home/opentitan

TB_ROOT=/home/opentitan/.tb_pr10097
SCRATCH_ROOT="${TB_ROOT}/scratch"
RUN_LOG="${TB_ROOT}/dvsim.log"

mkdir -p "${TB_ROOT}"

cat > hw/ip/spi_device/pre_dv/tb/spid_upload_tb.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

`timescale 1ns/1ps

module spid_upload_tb;
  import spi_device_pkg::*;

  localparam time SckHalfPeriod = 5ns;
  localparam time SysHalfPeriod = 4ns;
  localparam int unsigned CmdGrantDelayCycles = 2;
  localparam int unsigned AddrGrantDelayCycles = 2;
  localparam int unsigned TimeoutSysCycles = 200;
  localparam logic [31:0] ExpectedAddr = 32'hDEAD_BE00;
  localparam logic [7:0] ExpectedCmd = 8'h52;

  logic clk_i;
  logic sys_clk_i;
  logic rst_ni;
  logic sys_rst_ni;
  logic sys_csb_deasserted_pulse_i;

  sel_datapath_e sel_dp_i;
  sram_l2m_t sck_sram_o;
  sram_m2l_t sck_sram_i;
  sram_l2m_t sys_cmdfifo_sram_o;
  sram_m2l_t sys_cmdfifo_sram_i;
  logic sys_cmdfifo_gnt_i;
  sram_l2m_t sys_addrfifo_sram_o;
  sram_m2l_t sys_addrfifo_sram_i;
  logic sys_addrfifo_gnt_i;
  logic sys_cmdfifo_rvalid_o;
  logic sys_cmdfifo_rready_i;
  logic [7:0] sys_cmdfifo_rdata_o;
  logic sys_addrfifo_rvalid_o;
  logic sys_addrfifo_rready_i;
  logic [31:0] sys_addrfifo_rdata_o;
  logic s2p_valid_i;
  spi_byte_t s2p_byte_i;
  logic [BitCntW-1:0] s2p_bitcnt_i;
  logic p2s_valid_o;
  spi_byte_t p2s_data_o;
  logic p2s_sent_i;
  spi_mode_e spi_mode_i;
  logic cfg_addr_4b_en_i;
  cmd_info_t cmd_info_i;
  logic [CmdInfoIdxW-1:0] cmd_info_idx_i;
  io_mode_e io_mode_o;
  logic set_busy_o;
  logic sys_cmdfifo_notempty_o;
  logic sys_cmdfifo_full_o;
  logic sys_addrfifo_notempty_o;
  logic sys_addrfifo_full_o;
  logic [$clog2(SramCmdFifoDepth + 1)-1:0] sys_cmdfifo_depth_o;
  logic [$clog2(SramAddrFifoDepth + 1)-1:0] sys_addrfifo_depth_o;
  logic [$clog2(SramPayloadDepth * (SramDw / 8) + 1)-1:0] sys_payload_depth_o;

  logic [SramDw-1:0] mem [0:SramDepth-1];
  logic cmd_rsp_rvalid_q;
  logic [SramDw-1:0] cmd_rsp_rdata_q;
  logic addr_rsp_rvalid_q;
  logic [SramDw-1:0] addr_rsp_rdata_q;
  int unsigned cmd_holdoff_q;
  int unsigned addr_holdoff_q;

  wire cmd_read_fire = sys_cmdfifo_sram_o.req && sys_cmdfifo_gnt_i && !sys_cmdfifo_sram_o.we;
  wire addr_read_fire = sys_addrfifo_sram_o.req && sys_addrfifo_gnt_i && !sys_addrfifo_sram_o.we;

  spid_upload #(
    .CmdFifoBaseAddr  (SramCmdFifoIdx),
    .CmdFifoDepth     (SramCmdFifoDepth),
    .AddrFifoBaseAddr (SramAddrFifoIdx),
    .AddrFifoDepth    (SramAddrFifoDepth),
    .PayloadBaseAddr  (SramPayloadIdx),
    .PayloadDepth     (SramPayloadDepth),
    .SpiByte          ($bits(spi_byte_t))
  ) dut (.*);

  initial begin
    clk_i = 1'b0;
    forever #SckHalfPeriod clk_i = ~clk_i;
  end

  initial begin
    sys_clk_i = 1'b0;
    forever #SysHalfPeriod sys_clk_i = ~sys_clk_i;
  end

  always_comb begin
    sck_sram_i = '0;
    sys_cmdfifo_sram_i = '0;
    sys_addrfifo_sram_i = '0;
    sys_cmdfifo_sram_i.rvalid = cmd_rsp_rvalid_q;
    sys_cmdfifo_sram_i.rdata = cmd_rsp_rdata_q;
    sys_addrfifo_sram_i.rvalid = addr_rsp_rvalid_q;
    sys_addrfifo_sram_i.rdata = addr_rsp_rdata_q;
    sys_cmdfifo_gnt_i = sys_cmdfifo_sram_o.req && (cmd_holdoff_q == 0);
    sys_addrfifo_gnt_i = sys_addrfifo_sram_o.req && (addr_holdoff_q == 0);
  end

  always @(posedge clk_i) begin
    if (sck_sram_o.req && sck_sram_o.we) begin
      for (int unsigned byte_idx = 0; byte_idx < SramStrbW; byte_idx++) begin
        if (sck_sram_o.wstrb[byte_idx]) begin
          mem[sck_sram_o.addr][8*byte_idx +: 8] <= sck_sram_o.wdata[8*byte_idx +: 8];
        end
      end
      $display("[%0t] SCK write addr=%0h data=%0h wstrb=%0h", $time, sck_sram_o.addr,
               sck_sram_o.wdata, sck_sram_o.wstrb);
    end
  end

  always_ff @(posedge sys_clk_i or negedge sys_rst_ni) begin
    if (!sys_rst_ni) begin
      cmd_holdoff_q <= CmdGrantDelayCycles;
      addr_holdoff_q <= AddrGrantDelayCycles;
      cmd_rsp_rvalid_q <= 1'b0;
      cmd_rsp_rdata_q <= '0;
      addr_rsp_rvalid_q <= 1'b0;
      addr_rsp_rdata_q <= '0;
    end else begin
      if (sys_cmdfifo_sram_o.req && !sys_cmdfifo_gnt_i && (cmd_holdoff_q > 0)) begin
        cmd_holdoff_q <= cmd_holdoff_q - 1;
        $display("[%0t] Stall cmdfifo grant, remaining=%0d", $time, cmd_holdoff_q - 1);
      end
      if (sys_addrfifo_sram_o.req && !sys_addrfifo_gnt_i && (addr_holdoff_q > 0)) begin
        addr_holdoff_q <= addr_holdoff_q - 1;
        $display("[%0t] Stall addrfifo grant, remaining=%0d", $time, addr_holdoff_q - 1);
      end

      cmd_rsp_rvalid_q <= cmd_read_fire;
      if (cmd_read_fire) begin
        cmd_rsp_rdata_q <= mem[sys_cmdfifo_sram_o.addr];
        $display("[%0t] Grant cmdfifo read addr=%0h data=%0h", $time,
                 sys_cmdfifo_sram_o.addr, mem[sys_cmdfifo_sram_o.addr]);
      end

      addr_rsp_rvalid_q <= addr_read_fire;
      if (addr_read_fire) begin
        addr_rsp_rdata_q <= mem[sys_addrfifo_sram_o.addr];
        $display("[%0t] Grant addrfifo read addr=%0h data=%0h", $time,
                 sys_addrfifo_sram_o.addr, mem[sys_addrfifo_sram_o.addr]);
      end
    end
  end

  task automatic drive_byte(input logic [7:0] byte_i);
    begin
      @(negedge clk_i);
      s2p_valid_i = 1'b1;
      s2p_byte_i = byte_i;
      s2p_bitcnt_i = '0;
      @(negedge clk_i);
      s2p_valid_i = 1'b0;
      s2p_byte_i = '0;
    end
  endtask

  task automatic issue_upload_command();
    begin
      sel_dp_i = DpUpload;
      cmd_info_i = '{
        valid: 1'b1,
        opcode: ExpectedCmd,
        addr_mode: Addr3B,
        addr_swap_en: 1'b0,
        mbyte_en: 1'b0,
        dummy_en: 1'b0,
        dummy_size: '0,
        payload_en: 4'b0000,
        payload_dir: PayloadIn,
        payload_swap_en: 1'b0,
        upload: 1'b1,
        busy: 1'b0
      };
      drive_byte(ExpectedCmd);
      drive_byte(8'hDE);
      drive_byte(8'hAD);
      drive_byte(8'hBE);
      @(negedge clk_i);
      sel_dp_i = DpNone;
    end
  endtask

  task automatic expect_cmd();
    int unsigned cycles;
    begin
      cycles = 0;
      while (!sys_cmdfifo_rvalid_o && (cycles < TimeoutSysCycles)) begin
        @(posedge sys_clk_i);
        cycles++;
      end
      if (!sys_cmdfifo_rvalid_o) begin
        $fatal(1, "Timed out waiting for cmdfifo data");
      end
      if (sys_cmdfifo_rdata_o !== ExpectedCmd) begin
        $fatal(1, "Unexpected cmdfifo data: got %0h expected %0h", sys_cmdfifo_rdata_o,
               ExpectedCmd);
      end
      $display("[%0t] Observed cmdfifo data %0h", $time, sys_cmdfifo_rdata_o);
      @(negedge sys_clk_i);
      sys_cmdfifo_rready_i = 1'b1;
      @(negedge sys_clk_i);
      sys_cmdfifo_rready_i = 1'b0;
    end
  endtask

  task automatic expect_addr();
    int unsigned cycles;
    begin
      cycles = 0;
      while (!sys_addrfifo_rvalid_o && (cycles < TimeoutSysCycles)) begin
        @(posedge sys_clk_i);
        cycles++;
      end
      if (!sys_addrfifo_rvalid_o) begin
        $fatal(1, "Timed out waiting for addrfifo data");
      end
      if (sys_addrfifo_rdata_o !== ExpectedAddr) begin
        $fatal(1, "Unexpected addrfifo data: got %0h expected %0h", sys_addrfifo_rdata_o,
               ExpectedAddr);
      end
      $display("[%0t] Observed addrfifo data %0h", $time, sys_addrfifo_rdata_o);
      @(negedge sys_clk_i);
      sys_addrfifo_rready_i = 1'b1;
      @(negedge sys_clk_i);
      sys_addrfifo_rready_i = 1'b0;
    end
  endtask

  initial begin
    foreach (mem[idx]) mem[idx] = '0;
    rst_ni = 1'b0;
    sys_rst_ni = 1'b0;
    sys_csb_deasserted_pulse_i = 1'b0;
    sel_dp_i = DpNone;
    sys_cmdfifo_rready_i = 1'b0;
    sys_addrfifo_rready_i = 1'b0;
    s2p_valid_i = 1'b0;
    s2p_byte_i = '0;
    s2p_bitcnt_i = '0;
    p2s_sent_i = 1'b0;
    spi_mode_i = FlashMode;
    cfg_addr_4b_en_i = 1'b0;
    cmd_info_i = '{default: '0};
    cmd_info_idx_i = '0;

    repeat (6) @(posedge sys_clk_i);
    rst_ni = 1'b1;
    sys_rst_ni = 1'b1;

    repeat (2) @(posedge clk_i);
    issue_upload_command();
    expect_cmd();
    expect_addr();
    repeat (4) @(posedge sys_clk_i);
    $display("MSWE_PASS: spid_upload preserved cmd and addr entries across delayed grants");
    $display("TEST PASSED CHECKS");
    $finish;
  end

  initial begin
    repeat (TimeoutSysCycles * 2) @(posedge sys_clk_i);
    $fatal(1, "Simulation timed out");
  end

endmodule : spid_upload_tb
EOF

timeout 1800s python util/dvsim/dvsim.py \
