#!/bin/bash
cd /home/opentitan
set -uo pipefail

TEST_NAME="adc_ctrl_oneshot_handshake"
TB_DIR="/home/opentitan/.tb_adc_ctrl_oneshot_handshake"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

echo "HWE_BENCH_RESULTS_START"
trap 'echo "HWE_BENCH_RESULTS_END"' EXIT

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import adc_ctrl_reg_pkg::*;

  localparam logic [9:0] FirstSample  = 10'h155;
  localparam logic [9:0] SecondSample = 10'h2aa;

  logic clk_aon_i = 1'b0;
  logic rst_aon_ni = 1'b0;
  logic cfg_fsm_rst_i = 1'b0;
  logic cfg_adc_enable_i = 1'b0;
  logic cfg_oneshot_mode_i = 1'b1;
  logic cfg_lp_mode_i = 1'b0;
  logic [3:0] cfg_pwrup_time_i = '0;
  logic [23:0] cfg_wakeup_time_i = '0;
  logic [7:0] cfg_lp_sample_cnt_i = '0;
  logic [15:0] cfg_np_sample_cnt_i = '0;
  logic [NumAdcFilter-1:0] adc_ctrl_match_i = '0;
  logic [9:0] adc_d_i = '0;
  logic adc_d_val_i = 1'b0;

  logic adc_pd_o;
  logic [1:0] adc_chn_sel_o;
  logic chn0_val_we_o;
  logic chn1_val_we_o;
  logic [9:0] chn0_val_o;
  logic [9:0] chn1_val_o;
  logic adc_ctrl_done_o;
  logic oneshot_done_o;

  adc_ctrl_fsm dut (
    .clk_aon_i,
    .rst_aon_ni,
    .cfg_fsm_rst_i,
    .cfg_adc_enable_i,
    .cfg_oneshot_mode_i,
    .cfg_lp_mode_i,
    .cfg_pwrup_time_i,
    .cfg_wakeup_time_i,
    .cfg_lp_sample_cnt_i,
    .cfg_np_sample_cnt_i,
    .adc_ctrl_match_i,
    .adc_d_i,
    .adc_d_val_i,
    .adc_pd_o,
    .adc_chn_sel_o,
    .chn0_val_we_o,
    .chn1_val_we_o,
    .chn0_val_o,
    .chn1_val_o,
    .adc_ctrl_done_o,
    .oneshot_done_o
  );

  always #5 clk_aon_i = ~clk_aon_i;

  task automatic wait_for_ch0_phase();
    int timeout_cycles = 30;
    while ((adc_chn_sel_o !== 2'b01) && (timeout_cycles > 0)) begin
      @(negedge clk_aon_i);
      timeout_cycles--;
    end
    if (adc_chn_sel_o !== 2'b01) begin
      $fatal(1, "Timed out waiting for the channel-0 sample phase");
    end
  endtask

  initial begin
    repeat (2) @(posedge clk_aon_i);
    @(negedge clk_aon_i);
    rst_aon_ni = 1'b1;
    @(negedge clk_aon_i);
    cfg_adc_enable_i = 1'b1;

    wait_for_ch0_phase();

    // First ADC value remains valid for multiple cycles. The fixed RTL must
    // not progress to channel 1 until valid drops.
    @(negedge clk_aon_i);
    adc_d_i = FirstSample;
    adc_d_val_i = 1'b1;
    #1;
    if (oneshot_done_o) begin
      $fatal(1, "oneshot_done_o asserted too early on the first valid pulse");
    end

    repeat (2) begin
      @(negedge clk_aon_i);
      #1;
      if (oneshot_done_o) begin
        $fatal(1, "oneshot_done_o asserted before adc_d_val_i deasserted");
      end
      if (chn1_val_we_o) begin
        $fatal(1, "channel 1 sampled while adc_d_val_i stayed high");
      end
    end

    @(negedge clk_aon_i);
    adc_d_val_i = 1'b0;
    #1;
    if (oneshot_done_o) begin
      $fatal(1, "oneshot_done_o asserted during the valid-low handshake gap");
    end

    // The second valid pulse should now be consumed as the channel-1 sample.
    @(negedge clk_aon_i);
    adc_d_i = SecondSample;
    adc_d_val_i = 1'b1;
    #1;
    if (!oneshot_done_o) begin
      $fatal(1, "oneshot_done_o did not assert on the second valid pulse");
    end

    @(negedge clk_aon_i);
    #1;
    if (!chn1_val_we_o) begin
      $fatal(1, "channel 1 write enable missing on the second valid pulse");
    end
    if (chn0_val_o !== FirstSample) begin
      $fatal(1, "channel 0 captured the wrong sample value");
    end
    if (chn1_val_o !== SecondSample) begin
      $fatal(1, "channel 1 captured the wrong sample value");
    end

    adc_d_val_i = 1'b0;
    @(negedge clk_aon_i);
    #1;
    if (adc_pd_o !== 1'b1) begin
      $fatal(1, "FSM did not return to power-down after oneshot completion");
    end

    $display("TB_PASS");
    $finish;
  end

  initial begin
    #1000;
    $fatal(1, "Timed out waiting for the handshake scenario to complete");
  end
endmodule
EOF

timeout 1800s vcs -full64 -sverilog \
  -timescale=1ns/1ps \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log" \
  hw/ip/adc_ctrl/rtl/adc_ctrl_reg_pkg.sv \
  hw/ip/adc_ctrl/rtl/adc_ctrl_fsm.sv \
  "$TB_DIR/tb.sv"
compile_rc=$?

if [ $compile_rc -ne 0 ]; then
  [ -f "$TB_DIR/compile.log" ] && tail -n 200 "$TB_DIR/compile.log"
  echo "TEST: $TEST_NAME ... FAIL"
  exit $compile_rc
fi

timeout 1800s "$TB_DIR/simv" > "$TB_DIR/run.log" 2>&1
run_rc=$?
[ -f "$TB_DIR/run.log" ] && cat "$TB_DIR/run.log"

# VCS can still exit with code 0 after $fatal, so require the explicit
# success marker from the testbench as well.
if [ $run_rc -eq 0 ] && grep -q "TB_PASS" "$TB_DIR/run.log"; then
  echo "TEST: $TEST_NAME ... PASS"
  exit 0
fi

echo "TEST: $TEST_NAME ... FAIL"
exit 1

resolved_issues.body:
@tjaychen 
This is due to the update at #8322
Since EDN request relies on `reseed_interval_i`, SW can set it to 0 to send EDN request before the counter starts, or even cancel an unfinished EDN req as shown in the waveform, which violates the handshaking protocol.
`  assign edn_req = (reseed_cnt == reseed_interval_i);
`
![Screen Shot 2021-09-24 at 1 54 55 PM](https://user-images.githubusercontent.com/49293026/134738675-7a63aa44-d821-4c88-8844-9fa16229588f.png)

fix_patch:
diff --git a/hw/ip/keymgr/rtl/keymgr_reseed_ctrl.sv b/hw/ip/keymgr/rtl/keymgr_reseed_ctrl.sv
index 30ef36917015c..e96550975f58c 100644
--- a/hw/ip/keymgr/rtl/keymgr_reseed_ctrl.sv
+++ b/hw/ip/keymgr/rtl/keymgr_reseed_ctrl.sv
@@ -40,7 +40,7 @@ module keymgr_reseed_ctrl import keymgr_pkg::*; (
   logic [EdnCntWidth-1:0] edn_cnt;
   logic edn_txn_done;
   logic edn_done;
-  logic edn_req, edn_ack;
+  logic edn_req, edn_req_d, edn_req_q, edn_ack;
   logic [EdnWidth-1:0] edn_data;

   // This tracks how many edn rounds are required to fill up
@@ -77,14 +77,29 @@ module keymgr_reseed_ctrl import keymgr_pkg::*; (
     .clk_i,
     .rst_ni,
     .clr_i(edn_done),
-    .set_i(reseed_req_i & ~edn_req),
-    .set_cnt_i(reseed_interval_i),
+    .set_i('0),
+    .set_cnt_i('0),
     .en_i(~edn_req & ~first_use),
     .cnt_o(reseed_cnt),
     .err_o(cnt_err_o)
   );

-  assign edn_req = (reseed_cnt == reseed_interval_i);
+  // latch edn request to ensure even if interval is changed in the middle
+  // the req/ack protocol is respected
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (!rst_ni) begin
+      edn_req_q <= '0;
+    end else if (edn_done) begin
+      edn_req_q <= '0;
+    end else begin
+      edn_req_q <= edn_req_q | edn_req_d;
+    end
+  end
+
+  // An edn request can either come from counter or from external
+  assign edn_req_d = reseed_req_i | (~first_use & (reseed_cnt == reseed_interval_i));
+  assign edn_req = edn_req_q | edn_req_d;
+
   assign reseed_ack_o = reseed_req_i & edn_done;
   assign seed_en_o = edn_done;

