#!/bin/bash

cd /home/opentitan || exit 1

TEST_NAME="keymgr_reseed_req_hold"
TB_DIR="/home/opentitan/.tb_keymgr_reseed_ctrl"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_shims.sv" <<'EOF'
module prim_buf #(
  parameter int Width = 1
) (
  input        [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  prim_generic_buf #(
    .Width(Width)
  ) u_impl (
    .in_i,
    .out_o
  );
endmodule

module prim_flop #(
  parameter int               Width      = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  prim_generic_flop #(
    .Width(Width),
    .ResetValue(ResetValue)
  ) u_impl (
    .clk_i,
    .rst_ni,
    .d_i,
    .q_o
  );
endmodule

module prim_flop_2sync #(
  parameter int               Width      = 16,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  prim_generic_flop_2sync #(
    .Width(Width),
    .ResetValue(ResetValue)
  ) u_impl (
    .clk_i,
    .rst_ni,
    .d_i,
    .q_o
  );
endmodule
EOF

cat > "${TB_DIR}/keymgr_reseed_ctrl_tb.sv" <<'EOF'
module keymgr_reseed_ctrl_tb;
  import keymgr_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  wire clk_edn_i = clk_i;
  wire rst_edn_ni = rst_ni;

  logic reseed_req_i = 1'b0;
  logic [15:0] reseed_interval_i = 16'd3;
  logic reseed_ack_o;
  edn_pkg::edn_req_t edn_o;
  edn_pkg::edn_rsp_t edn_i;
  logic seed_en_o;
  logic [LfsrWidth-1:0] seed_o;
  logic cnt_err_o;

  bit request_seen;
  int cycle_count;

  keymgr_reseed_ctrl dut (
    .clk_i,
    .rst_ni,
    .clk_edn_i,
    .rst_edn_ni,
    .reseed_req_i,
    .reseed_ack_o,
    .reseed_interval_i,
    .edn_o,
    .edn_i,
    .seed_en_o,
    .seed_o,
    .cnt_err_o
  );

  always #5 clk_i = ~clk_i;

  // Return data immediately once the synchronized request is observed.
  always_comb begin
    edn_i.edn_ack = edn_o.edn_req;
    edn_i.edn_fips = 1'b1;
    edn_i.edn_bus = edn_o.edn_req ? 32'hA5A55A5A : '0;
  end

  // The bug is that edn_req can drop before the reseed transaction completes.
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      request_seen <= 1'b0;
      cycle_count <= 0;
    end else begin
      cycle_count <= cycle_count + 1;
      if (dut.edn_req) begin
        request_seen <= 1'b1;
      end
      if (request_seen && !seed_en_o && !dut.edn_req) begin
        $fatal(1, "edn_req dropped before seed_en_o asserted");
      end
      if (cnt_err_o) begin
        $fatal(1, "counter integrity error");
      end
      if (cycle_count > 80) begin
        $fatal(1, "timeout waiting for reseed to complete");
      end
    end
  end

  initial begin
    repeat (3) @(posedge clk_i);
    rst_ni = 1'b1;

    // Trigger the initial reseed, then change the interval while the request is pending.
    @(posedge clk_i);
    reseed_req_i = 1'b1;
    @(posedge clk_i);
    reseed_req_i = 1'b0;

    wait (dut.edn_req === 1'b1);
    @(posedge clk_i);
    reseed_interval_i = 16'd5;

    wait (seed_en_o === 1'b1);
    if (seed_o !== 64'hA5A55A5AA5A55A5A) begin
      $fatal(1, "unexpected seed value: %h", seed_o);
    end
    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

