set +e
vcs -full64 -sverilog -f "${TB_DIR}/files.f" -o "${TB_DIR}/simv" -l "${COMPILE_LOG}"
compile_rc=$?
if [ "${compile_rc}" -eq 0 ]; then
  "${TB_DIR}/simv" -l "${RUN_LOG}"
