#!/bin/bash
cd /home/opentitan || exit 1

TEST_NAME="tlul_sram_byte_partial_write_alignment"
TB_DIR="/home/opentitan/.tb_tlul_byte"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import top_pkg::*;
  import tlul_pkg::*;

  logic clk_i;
  logic rst_ni;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  tl_h2d_t tl_sram_o;
  tl_d2h_t tl_sram_i;
  logic error_i;

  tlul_sram_byte #(
    .EnableIntg(1'b1)
  ) dut (
    .clk_i,
    .rst_ni,
    .tl_i,
    .tl_o,
    .tl_sram_o,
    .tl_sram_i,
    .error_i
  );

  always #5 clk_i = ~clk_i;

  task automatic fail(input string msg);
    $display("TB_FAIL: %s", msg);
    $fatal(1, "%s", msg);
  endtask

  task automatic check_req(input string phase,
                           input tl_a_op_e exp_opcode,
                           input logic [TL_AW-1:0] exp_addr,
                           input logic [TL_SZW-1:0] exp_size,
                           input logic [TL_DBW-1:0] exp_mask,
                           input logic [TL_DW-1:0] exp_data,
                           input bit check_data);
    int cycles;
    cycles = 0;
    while (tl_sram_o.a_valid !== 1'b1) begin
      @(posedge clk_i);
      cycles++;
      if (cycles > 20) fail({phase, ": timeout waiting for tl_sram_o.a_valid"});
    end
    if (tl_sram_o.a_opcode !== exp_opcode) begin
      fail($sformatf("%s: opcode exp=%0d act=%0d", phase, exp_opcode, tl_sram_o.a_opcode));
    end
    if (tl_sram_o.a_address !== exp_addr) begin
      fail($sformatf("%s: address exp=0x%08x act=0x%08x", phase, exp_addr, tl_sram_o.a_address));
    end
    if (tl_sram_o.a_size !== exp_size) begin
      fail($sformatf("%s: size exp=%0d act=%0d", phase, exp_size, tl_sram_o.a_size));
    end
    if (tl_sram_o.a_mask !== exp_mask) begin
      fail($sformatf("%s: mask exp=0x%0x act=0x%0x", phase, exp_mask, tl_sram_o.a_mask));
    end
    if (check_data && tl_sram_o.a_data !== exp_data) begin
      fail($sformatf("%s: data exp=0x%08x act=0x%08x", phase, exp_data, tl_sram_o.a_data));
    end
    @(posedge clk_i);
  endtask

  task automatic drive_rsp(input tl_d_op_e opcode,
                           input logic [TL_DW-1:0] data,
                           input logic [TL_SZW-1:0] size);
    tl_sram_i.d_valid <= 1'b1;
    tl_sram_i.d_opcode <= opcode;
    tl_sram_i.d_data <= data;
    tl_sram_i.d_size <= size;
    do begin
      @(posedge clk_i);
    end while (tl_sram_o.d_ready !== 1'b1);
    tl_sram_i.d_valid <= 1'b0;
    tl_sram_i.d_opcode <= AccessAck;
    tl_sram_i.d_data <= '0;
    tl_sram_i.d_size <= '0;
  endtask

  initial begin
    int cycles;

    clk_i = 1'b0;
    rst_ni = 1'b0;
    error_i = 1'b0;
    tl_i = TL_H2D_DEFAULT;
    tl_sram_i = TL_D2H_DEFAULT;
    tl_sram_i.a_ready = 1'b1;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (3) @(posedge clk_i);

    tl_i.a_valid = 1'b1;
    tl_i.a_opcode = PutPartialData;
    tl_i.a_param = '0;
    tl_i.a_size = TL_SZW'(0);
    tl_i.a_source = '0;
    tl_i.a_address = TL_AW'(32'h0000_0005);
    tl_i.a_mask = TL_DBW'(4'b0010);
    tl_i.a_data = TL_DW'(32'h0000_AA00);
    tl_i.a_user = TL_A_USER_DEFAULT;
    tl_i.d_ready = 1'b1;

    check_req("read_phase",
              Get,
              TL_AW'(32'h0000_0004),
              TL_SZW'(2),
              TL_DBW'({TL_DBW{1'b1}}),
              '0,
