#!/bin/bash
cd /home/opentitan
set -uo pipefail
set +e

TBROOT=/home/opentitan/.tb_pwrmgr_abort
mkdir -p "$TBROOT"

cat > hw/ip/pwrmgr/dv/env/seq_lib/pwrmgr_smoke_vseq.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

// Reproducer for aborted low-power entry keeping low_power_o asserted.
class pwrmgr_smoke_vseq extends pwrmgr_base_vseq;
  `uvm_object_utils(pwrmgr_smoke_vseq)
  `uvm_object_new

  constraint fixed_timing_c {
    cycles_before_pwrok == 3;
    cycles_before_clks_ok == 3;
    cycles_between_clks_ok == 3;
    cycles_before_clk_status_on == 1;
    cycles_before_rst_lc_src == 1;
    cycles_before_otp_done == 1;
    cycles_before_lc_done == 1;
    cycles_before_clk_status_off == 1;
  }

  task body();
    bit saw_low_power;

    cfg.slow_clk_rst_vif.wait_for_reset(.wait_negedge(0));
    start_slow_fsm();
    start_fast_from_low_power();
    cfg.slow_clk_rst_vif.wait_clks(10);
    wait_for_fast_fsm_active();

    csr_wr(.ptr(ral.control.low_power_hint), .value(1'b1));
    wait_for_csr_to_propagate_to_slow_domain();
    cfg.pwrmgr_vif.update_cpu_sleeping(1'b1);

    // Keep flash busy so the entry aborts in FastPwrStateNvmIdleChk.
    cfg.pwrmgr_vif.update_otp_idle(1'b1);
    cfg.pwrmgr_vif.update_lc_idle(1'b1);
    cfg.pwrmgr_vif.update_flash_idle(1'b0);

    cfg.clk_rst_vif.wait_clks(cycles_before_clk_status_off);
    cfg.pwrmgr_vif.update_clk_status(1'b0);

    repeat (50) begin
      if (cfg.pwrmgr_vif.low_power === 1'b1) begin
        saw_low_power = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    if (!saw_low_power) begin
      `uvm_fatal(`gfn, "low_power_o never asserted during aborted low-power entry")
    end

    cfg.clk_rst_vif.wait_clks(20);
    if (cfg.pwrmgr_vif.low_power !== 1'b0) begin
      `uvm_fatal(`gfn, $sformatf("low_power_o stuck high after aborted low-power entry: %0b",
                                 cfg.pwrmgr_vif.low_power))
    end
  endtask

endclass : pwrmgr_smoke_vseq
EOF

python util/dvsim/dvsim.py hw/ip/pwrmgr/dv/pwrmgr_sim_cfg.hjson \
  -i pwrmgr_smoke \
  -t vcs \
  -r 1 \
  --fixed-seed 1 \
  --scratch-root "$TBROOT/scratch" \
  --purge
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [ $rc -eq 0 ]; then
  echo "TEST: pwrmgr_abort_low_power ... PASS"
else
  echo "TEST: pwrmgr_abort_low_power ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit $rc

