#!/bin/bash
set -u

cd /home/opentitan

TEST_NAME="spi_host_issue_8643_fsm"
TB_DIR="/home/opentitan/.tb_spi_host_issue_8643"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps

module spi_host_issue_8643_core_tb;
  import spi_host_cmd_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic en_i;
  command_t command_i;
  logic command_valid_i;
  logic command_ready_o;
  logic [31:0] tx_data_i;
  logic [3:0] tx_be_i;
  logic tx_valid_i;
  logic tx_ready_o;
  logic [31:0] rx_data_o;
  logic rx_valid_o;
  logic rx_ready_i;
  logic sck_o;
  logic [0:0] csb_o;
  logic [3:0] sd_o;
  logic [3:0] sd_en_o;
  logic [3:0] sd_i;
  logic rx_stall_o;
  logic tx_stall_o;
  logic active_o;
  logic sw_rst_i;

  logic [7:0] expected_bytes[$];
  logic [7:0] observed_bytes[$];
  logic [7:0] current_byte;
  int bit_idx;
  int unsigned csb_rise_count;
  bit seen_csb_low;
  bit early_csb_rise;

  spi_host_core #(
    .NumCS(1)
  ) dut (
    .clk_i,
    .rst_ni,
    .command_i,
    .command_valid_i,
    .command_ready_o,
    .en_i,
    .tx_data_i,
    .tx_be_i,
    .tx_valid_i,
    .tx_ready_o,
    .rx_data_o,
    .rx_valid_o,
    .rx_ready_i,
    .sw_rst_i,
    .sck_o,
    .csb_o,
    .sd_o,
    .sd_en_o,
    .sd_i,
    .rx_stall_o,
    .tx_stall_o,
    .active_o
  );

  always #5 clk_i = ~clk_i;

  always @(posedge sck_o) begin
    if (!csb_o[0] && sd_en_o[0]) begin
      current_byte[bit_idx] = sd_o[0];
      if (bit_idx == 0) begin
        observed_bytes.push_back(current_byte);
        bit_idx = 7;
      end else begin
        bit_idx--;
      end
    end
  end

  always @(negedge csb_o[0]) begin
    seen_csb_low = 1'b1;
  end

  always @(posedge csb_o[0]) begin
    if (seen_csb_low) begin
      csb_rise_count++;
      if (observed_bytes.size() < expected_bytes.size() || bit_idx != 7) begin
        early_csb_rise = 1'b1;
      end
    end
  end

  task automatic send_tx_word(input logic [31:0] data, input logic [3:0] be);
    tx_data_i  <= data;
    tx_be_i    <= be;
    tx_valid_i <= 1'b1;
    do begin
      @(posedge clk_i);
    end while (!tx_ready_o);
    tx_valid_i <= 1'b0;
  endtask

  task automatic send_command(input logic [8:0] len, input logic csaat);
    command_i.csid                <= '0;
    command_i.segment.speed       <= Standard;
    command_i.segment.cmd_wr_en   <= 1'b1;
    command_i.segment.cmd_rd_en   <= 1'b0;
    command_i.segment.len         <= len;
    command_i.segment.csaat       <= csaat;
    command_i.configopts.clkdiv   <= 16'd2;
    command_i.configopts.csnidle  <= 4'd0;
    command_i.configopts.csntrail <= 4'd0;
    command_i.configopts.csnlead  <= 4'd0;
    command_i.configopts.full_cyc <= 1'b0;
    command_i.configopts.cpha     <= 1'b0;
    command_i.configopts.cpol     <= 1'b0;
    command_valid_i               <= 1'b1;
    do begin
      @(posedge clk_i);
    end while (!command_ready_o);
    command_valid_i <= 1'b0;
  endtask

  task automatic tb_fail(input string msg);
    $display("TB_FAIL: %s", msg);
    $finish;
  endtask

  task automatic tb_pass;
    $display("TB_PASS");
    $finish;
  endtask

  task automatic check_results;
    if (early_csb_rise) begin
      tb_fail($sformatf("CSB deasserted before the final byte completed. observed=%0d rises=%0d",
                        observed_bytes.size(), csb_rise_count));
    end
    if (observed_bytes.size() != expected_bytes.size()) begin
      tb_fail($sformatf("Expected %0d transmitted bytes, saw %0d",
                        expected_bytes.size(), observed_bytes.size()));
    end
    foreach (expected_bytes[i]) begin
      if (observed_bytes[i] != expected_bytes[i]) begin
        tb_fail($sformatf("Unexpected byte %0d: expected 0x%02x saw 0x%02x",
                          i, expected_bytes[i], observed_bytes[i]));
      end
    end
    if (csb_rise_count != 1) begin
      tb_fail($sformatf("Expected one CSB rise after transfer, saw %0d", csb_rise_count));
    end
  endtask

  initial begin
    clk_i          = 1'b0;
    rst_ni         = 1'b0;
    en_i           = 1'b1;
    command_i      = '0;
    command_valid_i = 1'b0;
    tx_data_i      = '0;
    tx_be_i        = '0;
    tx_valid_i     = 1'b0;
    rx_ready_i     = 1'b1;
    sd_i           = '0;
    sw_rst_i       = 1'b0;
    csb_rise_count = 0;
    seen_csb_low   = 1'b0;
    early_csb_rise = 1'b0;
    current_byte   = '0;
    bit_idx        = 7;

    expected_bytes.push_back(8'h11);
    expected_bytes.push_back(8'h22);
    expected_bytes.push_back(8'h33);
    expected_bytes.push_back(8'h44);
    expected_bytes.push_back(8'h55);
    expected_bytes.push_back(8'h66);
    expected_bytes.push_back(8'h77);

    fork
      begin
        repeat (8000) @(posedge clk_i);
        tb_fail($sformatf("Global timeout. observed=%0d ready=%0b tx_ready=%0b active=%0b csb=%0b tx_stall=%0b",
                          observed_bytes.size(), command_ready_o, tx_ready_o, active_o, csb_o[0],
                          tx_stall_o));
      end
      begin
        repeat (5) @(posedge clk_i);
        rst_ni = 1'b1;
        repeat (3) @(posedge clk_i);

        send_tx_word(32'h00000011, 4'b0001);
        send_command(9'd0, 1'b1);

        send_tx_word(32'h55443322, 4'b1111);
        send_command(9'd3, 1'b1);

        send_tx_word(32'h00007766, 4'b0011);
        send_command(9'd1, 1'b0);

        repeat (4000) begin
          @(posedge clk_i);
          if (seen_csb_low && csb_o[0] && !active_o) begin
            check_results();
            tb_pass();
          end
        end

        tb_fail($sformatf("Timed out waiting for completion. observed=%0d active=%0b csb=%0b rises=%0d",
                          observed_bytes.size(), active_o, csb_o[0], csb_rise_count));
      end
    join_any
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<'EOF'
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/hw/ip/prim/rtl/prim_assert.sv
/home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_packer_fifo.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_reg_pkg.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_cmd_pkg.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_byte_merge.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_byte_select.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_shift_register.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_fsm.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_core.sv
/home/opentitan/.tb_spi_host_issue_8643/tb.sv
EOF

cd "$TB_DIR"

set +e
timeout 1800 vcs -full64 -sverilog -timescale=1ns/1ps \
  -f "$TB_DIR/files.f" \
  -top spi_host_issue_8643_core_tb \
  -l "$TB_DIR/compile.log" \
  >/dev/null 2>&1
compile_rc=$?
set -e

if [[ $compile_rc -ne 0 ]]; then
  echo "[INFO] VCS compile failed"
  tail -n 20 "$TB_DIR/compile.log" || true
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit $compile_rc
fi

set +e
timeout 300 ./simv -l "$TB_DIR/run.log" >/dev/null 2>&1
sim_rc=$?
set -e

result="FAIL"
final_rc=1
if grep -q "TB_PASS" "$TB_DIR/run.log"; then
  grep -m1 "TB_PASS" "$TB_DIR/run.log" || true
  result="PASS"
