// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class flash_ctrl_rma_mid_read_vseq extends flash_ctrl_host_ctrl_arb_vseq;
  `uvm_object_utils(flash_ctrl_rma_mid_read_vseq)
  `uvm_object_new

  localparam time RmaStateTimeoutNs = 500_000;  // 500 us

  virtual task body();
    data_q_t flash_op_data;
    logic [RmaSeedWidth-1:0] rma_seed;
    bit read_done;
    bit rma_progressed;

    `uvm_info(`gfn, "RMA mid-read buffer timing test", UVM_LOW)

    poll_fifo_status = 0;
    cfg.rma_ack_polling_stop = 0;

    init_flash_regions();

    `DV_CHECK_RANDOMIZE_FATAL(this)
    flash_op.op = FlashOpRead;
    flash_op.partition = FlashPartData;
    flash_op.num_words = FIFO_DEPTH;

    cfg.flash_mem_bkdr_init(flash_op.partition, FlashMemInitInvalidate);
    cfg.flash_mem_bkdr_write(.flash_op(flash_op), .scheme(FlashMemInitRandomize));

    rma_seed = 32'h1badc0de;

    fork
      begin : do_ctrl_read
        flash_ctrl_start_op(flash_op);
        flash_ctrl_read(flash_op.num_words, flash_op_data, poll_fifo_status);
        wait_flash_op_done();
        read_done = 1'b1;
      end

      begin : do_rma_req
        wait(cfg.flash_ctrl_vif.ctrl_fsm_idle == 1'b0);
        cfg.clk_rst_vif.wait_clks(10);

        fork
          begin : rma_thread
            `uvm_info(`gfn, "Issuing RMA request during controller read", UVM_LOW)
            send_rma_req(rma_seed);
          end

          begin : progress_thread
            `DV_SPINWAIT(wait(cfg.flash_ctrl_vif.rma_state == StRmaEraseWait);,
                         "Timed out waiting for rma_state StRmaEraseWait",
                         RmaStateTimeoutNs)
            rma_progressed = 1'b1;
          end
        join_any
        disable fork;
      end
    join

    `DV_CHECK_EQ(read_done, 1'b1, "Controller read did not complete")
    `DV_CHECK_EQ(rma_progressed, 1'b1, "RMA did not reach StRmaEraseWait")
  endtask
endclass
EOF

