#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="usbdev_suspend_data_toggle_retention"
TB_DIR="/home/opentitan/.tb_usbdev_suspend_data_toggle_retention"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
`timescale 1ns/1ps

module tb;
  import usb_consts_pkg::*;

  localparam logic [6:0] DevAddr = 7'h2a;
  localparam int unsigned Endpoint = 1;

  logic clk_48mhz_i;
  logic rst_ni;
  logic link_reset_i;
  logic link_active_i;
  logic [6:0] dev_addr_i;

  logic [3:0] out_ep_current_o;
  logic out_ep_data_put_o;
  logic [4:0] out_ep_put_addr_o;
  logic [7:0] out_ep_data_o;
  logic out_ep_newpkt_o;
  logic out_ep_acked_o;
  logic out_ep_rollback_o;
  logic [1:0] out_ep_setup_o;
  logic [1:0] out_ep_enabled_i;
  logic [1:0] out_ep_control_i;
  logic [1:0] out_ep_full_i;
  logic [1:0] out_ep_stall_i;
  logic [1:0] out_ep_iso_i;
  logic [1:0] data_toggle_clear_i;

  logic rx_pkt_start_i;
  logic rx_pkt_end_i;
  logic rx_pkt_valid_i;
  logic [3:0] rx_pid_i;
  logic [6:0] rx_addr_i;
  logic [3:0] rx_endp_i;
  logic rx_data_put_i;
  logic [7:0] rx_data_i;

  logic tx_pkt_start_o;
  logic tx_pkt_end_i;
  logic [3:0] tx_pid_o;

  usb_fs_nb_out_pe #(
    .NumOutEps(2),
    .MaxOutPktSizeByte(32)
  ) dut (
    .clk_48mhz_i(clk_48mhz_i),
    .rst_ni(rst_ni),
    .link_reset_i(link_reset_i),
    .link_active_i(link_active_i),
    .dev_addr_i(dev_addr_i),
    .out_ep_current_o(out_ep_current_o),
    .out_ep_data_put_o(out_ep_data_put_o),
    .out_ep_put_addr_o(out_ep_put_addr_o),
    .out_ep_data_o(out_ep_data_o),
    .out_ep_newpkt_o(out_ep_newpkt_o),
    .out_ep_acked_o(out_ep_acked_o),
    .out_ep_rollback_o(out_ep_rollback_o),
    .out_ep_setup_o(out_ep_setup_o),
    .out_ep_enabled_i(out_ep_enabled_i),
    .out_ep_control_i(out_ep_control_i),
    .out_ep_full_i(out_ep_full_i),
    .out_ep_stall_i(out_ep_stall_i),
    .out_ep_iso_i(out_ep_iso_i),
    .data_toggle_clear_i(data_toggle_clear_i),
    .rx_pkt_start_i(rx_pkt_start_i),
    .rx_pkt_end_i(rx_pkt_end_i),
    .rx_pkt_valid_i(rx_pkt_valid_i),
    .rx_pid_i(rx_pid_i),
    .rx_addr_i(rx_addr_i),
    .rx_endp_i(rx_endp_i),
    .rx_data_put_i(rx_data_put_i),
    .rx_data_i(rx_data_i),
    .tx_pkt_start_o(tx_pkt_start_o),
    .tx_pkt_end_i(tx_pkt_end_i),
    .tx_pid_o(tx_pid_o)
  );

  initial clk_48mhz_i = 1'b0;
  always #10 clk_48mhz_i = ~clk_48mhz_i;

  task automatic clear_rx_inputs();
    rx_pkt_start_i = 1'b0;
    rx_pkt_end_i = 1'b0;
    rx_pkt_valid_i = 1'b0;
    rx_pid_i = '0;
    rx_addr_i = '0;
    rx_endp_i = '0;
    rx_data_put_i = 1'b0;
    rx_data_i = '0;
  endtask

  task automatic tick();
    @(posedge clk_48mhz_i);
    #1;
  endtask

  task automatic drive_idle_cycle();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    tick();
  endtask

  task automatic send_out_token();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_end_i = 1'b1;
    rx_pkt_valid_i = 1'b1;
    rx_pid_i = UsbPidOut;
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    tick();
    if (!out_ep_newpkt_o || out_ep_current_o != Endpoint[3:0]) begin
      $fatal(1, "OUT token was not latched for endpoint %0d", Endpoint);
    end
  endtask

  task automatic start_data_phase();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_start_i = 1'b1;
    tick();
  endtask

  task automatic push_data_byte(input logic [7:0] value);
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    rx_data_put_i = 1'b1;
    rx_data_i = value;
    tick();
    if (!out_ep_data_put_o || out_ep_data_o != value) begin
      $fatal(1, "Payload byte was not accepted");
    end
  endtask

  task automatic finish_data_packet(
    input logic [3:0] data_pid,
    output logic rollback_seen,
    output logic ack_commit_seen
  );
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    rx_pkt_end_i = 1'b1;
    rx_pkt_valid_i = 1'b1;
    rx_pid_i = data_pid;
    rx_addr_i = DevAddr;
    rx_endp_i = Endpoint[3:0];
    #1;
    rollback_seen = out_ep_rollback_o && tx_pkt_start_o && (tx_pid_o == UsbPidAck);
    @(posedge clk_48mhz_i);
    #1;
    ack_commit_seen = out_ep_acked_o && tx_pkt_start_o && (tx_pid_o == UsbPidAck);
  endtask

  task automatic fail_test(input string message);
    $display("TB_FAIL: %0s", message);
    $finish;
  endtask

  task automatic send_out_transfer(
    input logic [3:0] data_pid,
    input bit expect_commit
  );
    logic rollback_seen;
    logic ack_commit_seen;

    send_out_token();
    drive_idle_cycle();
    start_data_phase();
    push_data_byte(8'ha5);
    finish_data_packet(data_pid, rollback_seen, ack_commit_seen);
    drive_idle_cycle();

    if (expect_commit) begin
      if (rollback_seen || !ack_commit_seen) begin
        fail_test($sformatf("Expected committed %0s packet, saw rollback=%0b commit=%0b",
                            (data_pid == UsbPidData0) ? "DATA0" : "DATA1",
                            rollback_seen, ack_commit_seen));
      end
    end else begin
      if (!rollback_seen || ack_commit_seen) begin
        fail_test($sformatf("Expected retransmit handling for %0s packet, saw rollback=%0b commit=%0b",
                            (data_pid == UsbPidData0) ? "DATA0" : "DATA1",
                            rollback_seen, ack_commit_seen));
      end
    end
  endtask

  initial begin
    rst_ni = 1'b0;
    link_reset_i = 1'b0;
    link_active_i = 1'b1;
    dev_addr_i = DevAddr;
    out_ep_enabled_i = 2'b10;
    out_ep_control_i = 2'b00;
    out_ep_full_i = 2'b00;
    out_ep_stall_i = 2'b00;
    out_ep_iso_i = 2'b00;
    data_toggle_clear_i = 2'b00;
    tx_pkt_end_i = 1'b0;
    clear_rx_inputs();

    repeat (3) tick();
    rst_ni = 1'b1;
    repeat (2) tick();

    // First DATA0 packet commits and moves the endpoint toggle to DATA1.
    send_out_transfer(UsbPidData0, 1'b1);

    // A suspend window must not clear the OUT data toggle.
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    link_active_i = 1'b0;
    tick();
    @(negedge clk_48mhz_i);
    clear_rx_inputs();
    link_active_i = 1'b1;
    tick();

    // After resume, the next new packet for the endpoint may legitimately be DATA1.
    // The buggy base revision treats it as a retransmission and rolls it back.
    send_out_transfer(UsbPidData1, 1'b1);

    $display("TB_PASS: USB OUT data toggle was retained across suspend");
    $finish(0);
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  +incdir+/home/opentitan/hw/ip/usbdev/rtl \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  /home/opentitan/hw/ip/usbdev/rtl/usb_consts_pkg.sv \
  /home/opentitan/hw/ip/usbdev/rtl/usb_fs_nb_out_pe.sv \
