class usbdev_setup_priority_over_stall_response_vseq extends usbdev_base_vseq;
  `uvm_object_utils(usbdev_setup_priority_over_stall_response_vseq)

  `uvm_object_new

  virtual task body();
    buf_init();

    // Accept both OUT and SETUP traffic on EP0, but STALL the OUT transaction.
    configure_out_trans(ep_default);
    configure_setup_trans(ep_default);
    csr_wr(.ptr(ral.out_stall[0].endpoint[ep_default]), .value(1'b1));

    // A long OUT packet that is rejected with STALL must still roll back internal RX state.
    send_prnd_out_packet(ep_default, PidTypeData0, .randomize_length(1'b0), .num_of_bytes(64));
    check_response_matches(PidTypeStall);

    // The next SETUP transaction must still be received correctly.
    send_prnd_setup_packet(ep_default);
    check_response_matches(PidTypeAck);
    check_rx_packet(ep_default, .setup(1'b1), .exp_buffer_id(setup_buffer_id),
                    .exp_byte_data(m_data_pkt.data), .buffer_known(1'b1));
  endtask
endclass : usbdev_setup_priority_over_stall_response_vseq
